import type { ExerciseQuestion } from "../types";

export const ADJECTIVE_QUESTIONS: ExerciseQuestion[] = [
  { id: "adj001", question: "His speech was very _____ and easy to understand. (clarity)", options: ["clarity", "clarify", "clear", "clearly"], correctIndex: 2, explanation: "'Clear' là tính từ ứng với danh từ 'clarity' và động từ 'clarify', nghĩa là 'rõ ràng, dễ hiểu'. Sau trạng từ chỉ mức độ 'very' cần một tính từ để miêu tả tính chất của 'his speech', nên 'clarity' (danh từ) không phù hợp. Lưu ý 'clearly' tuy cũng gần nghĩa nhưng là trạng từ (đuôi '-ly'), chỉ bổ nghĩa cho động từ chứ không đứng sau 'very' để tả danh từ như câu này." },
  { id: "adj002", question: "She gave a very _____ performance last night. (impression)", options: ["impression", "impress", "impressively", "impressive"], correctIndex: 3, explanation: "'Impressive' là tính từ được tạo từ danh từ 'impression' bằng đuôi '-ive', mang nghĩa 'gây ấn tượng'. Vị trí sau 'very' và trước danh từ 'performance' đòi hỏi một tính từ để bổ nghĩa, nên đáp án phải là 'impressive' chứ không phải danh từ 'impression'. Cẩn thận với 'impressively' - dạng trạng từ đuôi '-ly' này chỉ dùng để bổ nghĩa động từ, không đứng trước danh từ." },
  { id: "adj003", question: "The new policy is _____ to all employees. (benefit)", options: ["benefit", "beneficially", "beneficiary", "beneficial"], correctIndex: 3, explanation: "'Beneficial' là tính từ của danh từ/động từ 'benefit', mang đuôi tính từ '-al' và nghĩa 'có lợi'. Sau động từ liên kết 'is' cần một tính từ làm vị ngữ, đi kèm giới từ cố định 'beneficial to'. Phân biệt với 'beneficiary' (danh từ chỉ người được hưởng lợi) và 'beneficially' (trạng từ) - cả hai đều không thể đứng ở vị trí vị ngữ tính từ này." },
  { id: "adj004", question: "He is very _____ in his approach to problems. (creativity)", options: ["creativity", "create", "creatively", "creative"], correctIndex: 3, explanation: "'Creative' là tính từ của danh từ 'creativity', mang nghĩa 'sáng tạo'. Sau 'very' phải dùng tính từ để mô tả tính cách của chủ ngữ 'he', nên danh từ 'creativity' hay động từ 'create' đều sai vị trí. Đừng nhầm với 'creatively' - trạng từ đuôi '-ly' này chỉ bổ nghĩa cho động từ, không thể đứng sau 'very' để tả người." },
  { id: "adj005", question: "The test results were _____ with our predictions. (consistency)", options: ["consistency", "consist", "consistently", "consistent"], correctIndex: 3, explanation: "'Consistent' là tính từ của danh từ 'consistency', đuôi '-ent' và có nghĩa 'nhất quán, phù hợp'. Sau động từ 'were' cần tính từ làm vị ngữ, đồng thời đi với giới từ quen thuộc 'consistent with'. 'Consistently' (trạng từ) hay 'consist' (động từ) không thể thay thế được ở vị trí vị ngữ này." },
  { id: "adj006", question: "She is very _____ when it comes to meeting deadlines. (reliability)", options: ["reliability", "rely", "reliably", "reliable"], correctIndex: 3, explanation: "'Reliable' là tính từ của danh từ 'reliability' và động từ 'rely', đuôi '-able' mang nghĩa 'đáng tin cậy'. Sau 'very' cần một tính từ để mô tả tính cách của 'she', nên danh từ 'reliability' không phù hợp về ngữ pháp. So với 'reliably' (trạng từ, bổ nghĩa động từ), 'reliable' mới đúng vì ở đây ta đang mô tả bản thân người, chứ không mô tả cách thức hành động." },
  { id: "adj007", question: "The situation was extremely _____ for everyone involved. (stress)", options: ["stress", "stressed", "stressful", "stressing"], correctIndex: 2, explanation: "'Stressful' là tính từ mang đuôi '-ful', dùng để mô tả một sự việc/tình huống gây ra căng thẳng cho người khác - ở đây là 'the situation'. Cần phân biệt rõ với 'stressed' (đuôi '-ed'), chỉ dùng cho người cảm thấy căng thẳng, ví dụ 'I feel stressed'. Vì chủ ngữ là 'the situation' (vật gây ra cảm xúc) chứ không phải người, nên phải chọn dạng '-ful' chứ không phải '-ed'." },
  { id: "adj008", question: "He was completely _____ by the magic show. (fascination)", options: ["fascination", "fascinate", "fascinated", "fascinating"], correctIndex: 2, explanation: "'Fascinated' là tính từ đuôi '-ed', diễn tả cảm xúc của người bị cuốn hút - ở đây chủ ngữ là 'he' nên phải dùng dạng này. Cấu trúc quen thuộc là 'be fascinated by something'. Đối lập với 'fascinating' (đuôi '-ing'), vốn dùng để mô tả bản thân sự vật/sự việc gây ra sự cuốn hút, ví dụ 'the show was fascinating' - không phù hợp khi chủ ngữ là người như câu này." },
  { id: "adj009", question: "The documentary was absolutely _____. (fascination)", options: ["fascination", "fascinate", "fascinated", "fascinating"], correctIndex: 3, explanation: "'Fascinating' (đuôi '-ing') mô tả đặc tính của sự vật gây ra sự cuốn hút, ở đây là 'the documentary' - vật gây cảm xúc chứ không phải người cảm nhận. Sau trạng từ nhấn mạnh 'absolutely' cần một tính từ làm vị ngữ. Nhớ phân biệt với 'fascinated' (đuôi '-ed') - chỉ dùng khi chủ ngữ là người, ví dụ 'I was fascinated', không dùng cho vật như phim tài liệu." },
  { id: "adj010", question: "She felt _____ after finishing the marathon. (exhaustion)", options: ["exhaustion", "exhaust", "exhausting", "exhausted"], correctIndex: 3, explanation: "'Exhausted' (đuôi '-ed') diễn tả cảm giác kiệt sức của người, phù hợp với chủ ngữ 'she' sau động từ cảm giác 'felt'. Ngược lại, 'exhausting' (đuôi '-ing') mô tả bản thân sự việc/hoạt động gây ra sự kiệt sức, ví dụ 'the marathon was exhausting'. Vì câu hỏi mô tả cảm xúc của người chạy chứ không phải bản thân cuộc thi, đáp án đúng là 'exhausted'." },
  { id: "adj011", question: "The long journey was _____ for all the passengers. (exhaustion)", options: ["exhaustion", "exhaust", "exhausted", "exhausting"], correctIndex: 3, explanation: "'Exhausting' (đuôi '-ing') mô tả sự vật/sự việc gây ra cảm giác kiệt sức - ở đây là 'the long journey' đối với hành khách. Sau động từ liên kết 'was' cần tính từ làm vị ngữ. Phân biệt với 'exhausted' (đuôi '-ed'), chỉ dùng cho người cảm thấy kiệt sức chứ không dùng để mô tả bản thân chuyến đi như trong câu này." },
  { id: "adj012", question: "The country's economy remains _____ despite global challenges. (stability)", options: ["stability", "stabilize", "stably", "stable"], correctIndex: 3, explanation: "'Stable' là tính từ của danh từ 'stability', mang nghĩa 'ổn định'. Sau động từ liên kết 'remains' cần một tính từ làm vị ngữ để mô tả trạng thái của 'the country's economy'. 'Stably' (trạng từ) và 'stabilize' (động từ) đều sai vị trí ngữ pháp so với 'stable'." },
  { id: "adj013", question: "Her _____ behavior in class disturbed everyone. (disruption)", options: ["disruption", "disrupt", "disruptively", "disruptive"], correctIndex: 3, explanation: "'Disruptive' là tính từ của danh từ 'disruption', đuôi '-ive' mang nghĩa 'gây rối, làm gián đoạn'. Vị trí trước danh từ 'behavior' cần một tính từ để bổ nghĩa trực tiếp. So với 'disruptively' (trạng từ, bổ nghĩa động từ), 'disruptive' mới đứng được ngay trước danh từ như ở đây." },
  { id: "adj014", question: "The new medication proved _____ in clinical trials. (effectiveness)", options: ["effectiveness", "effectively", "effective", "effect"], correctIndex: 2, explanation: "'Effective' là tính từ của danh từ 'effectiveness', mang nghĩa 'hiệu quả'. Sau động từ 'proved' (chứng tỏ là) cần một tính từ làm bổ ngữ, nên danh từ 'effectiveness' hay danh từ gốc 'effect' đều không phù hợp về mặt cấu trúc. Trạng từ 'effectively' cũng sai vì nó chỉ bổ nghĩa cho động từ, không làm bổ ngữ chủ ngữ ở đây." },
  { id: "adj015", question: "The results were considered _____ by the committee. (acceptability)", options: ["acceptability", "accept", "acceptably", "acceptable"], correctIndex: 3, explanation: "'Acceptable' là tính từ của danh từ 'acceptability', đuôi '-able' nghĩa là 'có thể chấp nhận được'. Đứng sau động từ 'considered' làm vị ngữ, chỗ trống cần tính từ chứ không phải danh từ 'acceptability' hay trạng từ 'acceptably'. Đây là mẫu câu quen thuộc 'consider something + adjective'." },
  { id: "adj016", question: "She is particularly _____ in science and technology. (knowledge)", options: ["knowledge", "know", "knowledgeable", "knowingly"], correctIndex: 2, explanation: "'Knowledgeable' là tính từ tạo từ danh từ 'knowledge' bằng đuôi '-able', mang nghĩa 'am hiểu, có kiến thức sâu rộng'. Sau 'particularly' cần một tính từ, đi cùng giới từ quen thuộc 'knowledgeable in'. Phân biệt với 'knowingly' (trạng từ, nghĩa 'một cách cố ý') - hoàn toàn khác nghĩa và sai vị trí ngữ pháp." },
  { id: "adj017", question: "His _____ decision cost the company millions of dollars. (rashness)", options: ["rashness", "rashly", "rash", "rashes"], correctIndex: 2, explanation: "'Rash' là tính từ tương ứng với danh từ 'rashness', mang nghĩa 'hấp tấp, bốc đồng'. Đứng ngay trước danh từ 'decision' nên cần một tính từ để bổ nghĩa trực tiếp. 'Rashly' (trạng từ) hay 'rashness' (danh từ) đều không thể đứng ở vị trí bổ nghĩa danh từ như thế này." },
  { id: "adj018", question: "The new software is much more _____ than the old version. (efficiency)", options: ["efficiency", "efficiently", "efficient", "efficience"], correctIndex: 2, explanation: "'Efficient' là tính từ của danh từ 'efficiency', nghĩa 'hiệu quả, năng suất'. Sau cấu trúc so sánh hơn 'more' cần một tính từ, nên danh từ 'efficiency' hay trạng từ 'efficiently' đều không hợp lý ở đây. Ghi nhớ mẫu tính từ so sánh: 'more + adjective + than'." },
  { id: "adj019", question: "She was _____ when she heard the good news. (delight)", options: ["delight", "delighting", "delightedly", "delighted"], correctIndex: 3, explanation: "'Delighted' (đuôi '-ed') diễn tả cảm xúc vui sướng của người, phù hợp với chủ ngữ 'she'. Cần phân biệt với 'delightful' (đuôi '-ful'), vốn dùng để mô tả sự vật/sự việc mang lại niềm vui, ví dụ 'a delightful surprise' chứ không dùng cho người cảm nhận như câu này. 'Delighting' cũng không phải cách dùng chuẩn trong trường hợp này." },
  { id: "adj020", question: "The view from the top was _____. (delight)", options: ["delight", "delighting", "delighted", "delightful"], correctIndex: 3, explanation: "'Delightful' (đuôi '-ful') mô tả sự vật gây ra niềm vui thích - ở đây là 'the view from the top'. Sau động từ liên kết 'was' cần tính từ làm vị ngữ. Phân biệt với 'delighted' (đuôi '-ed'), chỉ dùng cho người cảm thấy vui sướng, ví dụ 'she was delighted', không phù hợp để tả cảnh vật như trong câu này." },
  { id: "adj021", question: "The experiment yielded some _____ results. (surprise)", options: ["surprise", "surprisingly", "surprised", "surprising"], correctIndex: 3, explanation: "'Surprising' (đuôi '-ing') mô tả sự vật/kết quả gây ra sự ngạc nhiên - ở đây là 'results'. Chỗ trống đứng trước danh từ 'results' cần một tính từ bổ nghĩa trực tiếp. Đối lập với 'surprised' (đuôi '-ed'), chỉ dùng cho người cảm thấy ngạc nhiên chứ không dùng để tả bản thân kết quả thí nghiệm." },
  { id: "adj022", question: "She was _____ to see him at the party. (surprise)", options: ["surprise", "surprisingly", "surprising", "surprised"], correctIndex: 3, explanation: "'Surprised' (đuôi '-ed') diễn tả cảm xúc ngạc nhiên của người, đúng với chủ ngữ 'she'. Sau động từ liên kết 'was' cần tính từ làm vị ngữ, đi kèm cấu trúc 'surprised to do something'. Phân biệt với 'surprising' (đuôi '-ing') - chỉ dùng để mô tả sự việc gây ngạc nhiên, không dùng cho người cảm nhận như ở đây." },
  { id: "adj023", question: "The committee found his proposal _____ and practical. (innovate)", options: ["innovate", "innovation", "innovatively", "innovative"], correctIndex: 3, explanation: "'Innovative' là tính từ tạo từ động từ 'innovate' bằng đuôi '-ive', nghĩa là 'sáng tạo, đổi mới'. Đây là mẫu câu 'find something + adjective', nên chỗ trống cần một tính từ để bổ nghĩa cho 'his proposal', không thể dùng động từ 'innovate' hay danh từ 'innovation'. Trạng từ 'innovatively' cũng sai vì không thể đứng ở vị trí bổ ngữ tân ngữ này." },
  { id: "adj024", question: "She has a _____ understanding of the subject matter. (comprehension)", options: ["comprehension", "comprehend", "comprehensively", "comprehensive"], correctIndex: 3, explanation: "'Comprehensive' là tính từ của danh từ 'comprehension', mang đuôi '-ive' và nghĩa 'toàn diện, đầy đủ'. Đứng trước danh từ 'understanding' nên cần một tính từ để bổ nghĩa trực tiếp. Trạng từ 'comprehensively' không thể đứng ở vị trí này vì trạng từ không bổ nghĩa cho danh từ." },
  { id: "adj025", question: "The working conditions in the factory were _____. (hazard)", options: ["hazard", "hazardously", "hazardous", "hazarding"], correctIndex: 2, explanation: "'Hazardous' là tính từ của danh từ 'hazard', đuôi '-ous' mang nghĩa 'nguy hiểm, rủi ro'. Sau động từ liên kết 'were' cần tính từ làm vị ngữ để mô tả 'the working conditions'. 'Hazardously' (trạng từ) và 'hazarding' (dạng V-ing của động từ) đều không phù hợp ở vị trí này." },
  { id: "adj026", question: "He gave a very _____ account of the events that took place. (detail)", options: ["detail", "detailing", "detailedly", "detailed"], correctIndex: 3, explanation: "'Detailed' là tính từ tạo từ danh từ 'detail' bằng đuôi '-ed', mang nghĩa 'chi tiết, tỉ mỉ'. Sau 'very' và trước danh từ 'account' cần một tính từ để bổ nghĩa. Chú ý đây không phải cặp tính từ '-ed/-ing' chỉ cảm xúc, mà 'detailed' đơn thuần là tính từ mô tả mức độ chi tiết của sự vật." },
  { id: "adj027", question: "The atmosphere in the office is very _____. (collaborate)", options: ["collaborate", "collaboration", "collaborating", "collaborative"], correctIndex: 3, explanation: "'Collaborative' là tính từ tạo từ động từ 'collaborate' bằng đuôi '-ive', nghĩa là 'mang tính hợp tác'. Sau 'very' cần một tính từ làm vị ngữ mô tả 'the atmosphere in the office'. Danh từ 'collaboration' và động từ dạng '-ing' 'collaborating' đều sai vị trí ngữ pháp so với tính từ 'collaborative'." },
  { id: "adj028", question: "She made a very _____ choice for her future career. (wisdom)", options: ["wisdom", "wisely", "wise", "wised"], correctIndex: 2, explanation: "'Wise' là tính từ của danh từ 'wisdom', nghĩa 'khôn ngoan, sáng suốt'. Đứng sau 'very' và trước danh từ 'choice' cần một tính từ. 'Wisely' (trạng từ) hay 'wised' (không phải dạng chuẩn) đều không phù hợp ở vị trí bổ nghĩa danh từ này." },
  { id: "adj029", question: "The company's growth this year has been _____. (remark)", options: ["remark", "remarkably", "remarked", "remarkable"], correctIndex: 3, explanation: "'Remarkable' là tính từ tạo từ 'remark' bằng đuôi '-able', mang nghĩa 'đáng chú ý, nổi bật'. Sau 'has been' cần một tính từ làm vị ngữ. Phân biệt với 'remarkably' (trạng từ) - dùng để bổ nghĩa động từ hoặc tính từ khác, không thể tự đứng làm vị ngữ như 'remarkable' ở đây." },
  { id: "adj030", question: "His _____ attitude toward learning inspired everyone. (enthusiasm)", options: ["enthusiasm", "enthuse", "enthusiastically", "enthusiastic"], correctIndex: 3, explanation: "'Enthusiastic' là tính từ của danh từ 'enthusiasm', đuôi '-ic' mang nghĩa 'nhiệt tình, hăng hái'. Đứng trước danh từ 'attitude' nên cần một tính từ bổ nghĩa trực tiếp. So với 'enthusiastically' (trạng từ, bổ nghĩa động từ), 'enthusiastic' mới đúng vị trí đứng trước danh từ như trong câu." },
  { id: "adj031", question: "The _____ conditions led to the project's failure. (adversity)", options: ["adversity", "adversely", "adverse", "adversary"], correctIndex: 2, explanation: "'Adverse' là tính từ của danh từ 'adversity', mang nghĩa 'bất lợi, tiêu cực'. Đứng trước danh từ 'conditions' cần một tính từ để bổ nghĩa. Lưu ý không nhầm với 'adversary' (danh từ nghĩa 'đối thủ') - khác nghĩa hoàn toàn và cũng sai vị trí ngữ pháp." },
  { id: "adj032", question: "She is _____ of making such a serious mistake. (capability)", options: ["capability", "capably", "capable", "capacity"], correctIndex: 2, explanation: "'Capable' là tính từ của danh từ 'capability', nghĩa 'có khả năng'. Sau động từ 'is' cần tính từ làm vị ngữ, đi cùng giới từ cố định 'capable of'. Phân biệt với 'capacity' (danh từ khác nghĩa, chỉ 'sức chứa/năng lực') - không thể thay thế 'capable' ở vị trí tính từ này." },
  { id: "adj033", question: "His presentation was very _____ and well-organized. (structure)", options: ["structure", "structurally", "structured", "structural"], correctIndex: 2, explanation: "'Structured' là tính từ tạo từ danh từ 'structure' bằng đuôi '-ed', mang nghĩa 'có cấu trúc, mạch lạc'. Sau 'very' cần tính từ làm vị ngữ mô tả 'his presentation'. 'Structural' (tính từ khác nghĩa, liên quan đến kết cấu vật lý) không phù hợp ngữ nghĩa bằng 'structured' trong ngữ cảnh một bài thuyết trình có tổ chức." },
  { id: "adj034", question: "The doctor recommended a _____ diet and regular exercise. (balance)", options: ["balance", "balancing", "balanced", "balancedly"], correctIndex: 2, explanation: "'Balanced' là tính từ tạo từ danh từ 'balance' bằng đuôi '-ed', nghĩa 'cân bằng'. Đứng trước danh từ 'diet' cần một tính từ để bổ nghĩa trực tiếp. 'Balancing' (V-ing) mang nghĩa 'đang cân bằng' chủ động chứ không mô tả tính chất tĩnh của chế độ ăn như 'balanced'." },
  { id: "adj035", question: "Her approach to the problem was completely _____. (logic)", options: ["logic", "logically", "logical", "logician"], correctIndex: 2, explanation: "'Logical' là tính từ của danh từ 'logic', đuôi '-al' mang nghĩa 'hợp lý, logic'. Sau 'was' cần tính từ làm vị ngữ, và sau 'completely' càng khẳng định vị trí này cần tính từ. 'Logically' (trạng từ) không thể tự đứng làm vị ngữ như 'logical' ở đây." },
  { id: "adj036", question: "The situation is becoming increasingly _____. (complexity)", options: ["complexity", "complexly", "complex", "complexion"], correctIndex: 2, explanation: "'Complex' là tính từ của danh từ 'complexity', nghĩa 'phức tạp'. Sau trạng từ 'increasingly' (ngày càng) cần một tính từ làm vị ngữ. 'Complexion' (danh từ khác nghĩa, chỉ 'làn da/diện mạo') hoàn toàn không liên quan và sai cả nghĩa lẫn ngữ pháp." },
  { id: "adj037", question: "He is _____ to accept new ideas and perspectives. (openness)", options: ["openness", "openly", "open", "opening"], correctIndex: 2, explanation: "'Open' là tính từ tương ứng với danh từ 'openness', nghĩa 'cởi mở'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'open to'. 'Openly' (trạng từ) và 'opening' (danh động từ/danh từ) đều không phù hợp vị trí ngữ pháp này." },
  { id: "adj038", question: "The plan is both _____ and cost-effective. (practicality)", options: ["practicality", "practically", "practitioner", "practical"], correctIndex: 3, explanation: "'Practical' là tính từ của danh từ 'practicality', nghĩa 'thiết thực, khả thi'. Cấu trúc 'both...and' nối hai tính từ song song, mà 'cost-effective' đã là tính từ nên chỗ trống cũng phải là tính từ 'practical'. 'Practitioner' (danh từ chỉ người hành nghề) hoàn toàn lạc đề về nghĩa." },
  { id: "adj039", question: "She is very _____ to criticism from her peers. (sensitivity)", options: ["sensitivity", "sensitively", "sensitive", "sensible"], correctIndex: 2, explanation: "'Sensitive' là tính từ của danh từ 'sensitivity', nghĩa 'nhạy cảm', đi với giới từ 'sensitive to'. Sau 'very' cần tính từ, và cần phân biệt với 'sensible' - tuy cũng là tính từ nhưng nghĩa khác hẳn ('biết điều, hợp lý'), không phù hợp với ngữ cảnh nhạy cảm trước lời phê bình." },
  { id: "adj040", question: "The contract terms are not _____ to any further changes. (flex)", options: ["flex", "flexing", "flexibility", "flexible"], correctIndex: 3, explanation: "'Flexible' là tính từ của danh từ/động từ 'flex', đuôi '-ible' mang nghĩa 'linh hoạt'. Sau 'not' cần một tính từ để phủ định, mô tả 'the contract terms'. 'Flexibility' (danh từ) không thể đứng ngay sau 'not' ở vị trí vị ngữ tính từ như thế này." },
  { id: "adj041", question: "The lecture was very _____ and thought-provoking. (stimulation)", options: ["stimulation", "stimulate", "stimulatingly", "stimulating"], correctIndex: 3, explanation: "'Stimulating' (đuôi '-ing') mô tả sự vật/hoạt động kích thích tư duy người khác - ở đây là 'the lecture'. Sau 'very' cần tính từ làm vị ngữ. Nếu chủ ngữ là người cảm thấy được kích thích thì phải dùng 'stimulated' (đuôi '-ed'), nhưng ở câu này chủ ngữ là bài giảng nên phải chọn dạng '-ing'." },
  { id: "adj042", question: "Her writing style is both _____ and engaging. (conciseness)", options: ["conciseness", "concisely", "concise", "concision"], correctIndex: 2, explanation: "'Concise' là tính từ của danh từ 'conciseness', nghĩa 'ngắn gọn, súc tích'. Trong cấu trúc 'both...and' nối với tính từ 'engaging', chỗ trống cũng cần một tính từ. 'Concision' (danh từ) không thể đứng song song với tính từ 'engaging' trong cấu trúc này." },
  { id: "adj043", question: "The two sides finally reached a _____ agreement. (mutuality)", options: ["mutuality", "mutually", "mutualness", "mutual"], correctIndex: 3, explanation: "'Mutual' là tính từ của danh từ 'mutuality', nghĩa 'chung, qua lại'. Đứng trước danh từ 'agreement' cần một tính từ để bổ nghĩa. 'Mutually' (trạng từ) chỉ bổ nghĩa cho động từ hoặc tính từ khác, không thể đứng trực tiếp trước danh từ như 'mutual'." },
  { id: "adj044", question: "She is _____ for her bold and unique fashion choices. (renown)", options: ["renown", "renowned", "renownedly", "renowning"], correctIndex: 1, explanation: "'Renowned' là tính từ (thực chất là dạng quá khứ phân từ của 'renown') mang nghĩa 'nổi tiếng, lừng danh'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'renowned for'. Danh từ gốc 'renown' không thể đứng trực tiếp sau 'is' để đóng vai trò vị ngữ tính từ ở đây." },
  { id: "adj045", question: "His research has been very _____ in the field of medicine. (influence)", options: ["influence", "influencing", "influencer", "influential"], correctIndex: 3, explanation: "'Influential' là tính từ của danh từ 'influence', đuôi '-ial' mang nghĩa 'có ảnh hưởng lớn'. Sau 'has been' và 'very' cần tính từ làm vị ngữ. 'Influencer' (danh từ chỉ người có tầm ảnh hưởng, ví dụ trên mạng xã hội) không phù hợp ngữ pháp lẫn ngữ cảnh của câu." },
  { id: "adj046", question: "The new policy is _____ for small businesses in the region. (harm)", options: ["harm", "harmed", "harmfully", "harmful"], correctIndex: 3, explanation: "'Harmful' là tính từ của danh từ/động từ 'harm', đuôi '-ful' mang nghĩa 'có hại'. Sau động từ liên kết 'is' cần tính từ làm vị ngữ. 'Harmed' (quá khứ phân từ, nghĩa 'bị hại') mang nghĩa bị động khác hẳn, không phù hợp để mô tả tác động của chính sách như câu này." },
  { id: "adj047", question: "She was very _____ about starting her own business. (optimism)", options: ["optimism", "optimistically", "optimize", "optimistic"], correctIndex: 3, explanation: "'Optimistic' là tính từ của danh từ 'optimism', đuôi '-ic' mang nghĩa 'lạc quan'. Sau 'very' cần tính từ, đi cùng giới từ 'optimistic about'. Động từ 'optimize' (nghĩa 'tối ưu hóa') hoàn toàn khác nghĩa và không thể thay thế ở vị trí này." },
  { id: "adj048", question: "The timing of the announcement seemed _____. (intention)", options: ["intention", "intend", "intentionally", "intentional"], correctIndex: 3, explanation: "'Intentional' là tính từ của danh từ 'intention', nghĩa 'có chủ đích, cố ý'. Sau động từ liên kết 'seemed' cần tính từ làm vị ngữ. 'Intentionally' (trạng từ) không thể tự đứng làm vị ngữ, còn danh từ 'intention' cũng sai vị trí ngữ pháp so với tính từ 'intentional'." },
  { id: "adj049", question: "The road conditions were _____ due to heavy rain. (danger)", options: ["danger", "dangerously", "dangerous", "endangered"], correctIndex: 2, explanation: "'Dangerous' là tính từ của danh từ 'danger', nghĩa 'nguy hiểm'. Sau 'were' cần tính từ làm vị ngữ mô tả 'the road conditions'. Phân biệt với 'endangered' (nghĩa 'bị đe dọa/nguy cấp', thường dùng cho loài vật, ví dụ 'endangered species') - nghĩa khác hẳn và không hợp ngữ cảnh đường xá ở đây." },
  { id: "adj050", question: "She has a very _____ manner when dealing with clients. (profession)", options: ["profession", "professionally", "professionalism", "professional"], correctIndex: 3, explanation: "'Professional' là tính từ của danh từ 'profession', nghĩa 'chuyên nghiệp'. Đứng trước danh từ 'manner' cần một tính từ để bổ nghĩa. 'Professionalism' (danh từ trừu tượng) và 'professionally' (trạng từ) đều sai vị trí so với tính từ 'professional' đứng trước danh từ." },
  { id: "adj051", question: "The report was extremely _____ and covered every aspect of the issue. (thorough)", options: ["thoroughness", "thoroughly", "thorough", "thorougher"], correctIndex: 2, explanation: "'Thorough' là tính từ gốc, có danh từ liên quan là 'thoroughness', mang nghĩa 'kỹ lưỡng, toàn diện'. Sau 'extremely' cần tính từ làm vị ngữ. 'Thoroughly' (trạng từ) chỉ bổ nghĩa cho động từ, không thể đứng sau 'extremely' để mô tả tính chất của 'the report' như ở đây." },
  { id: "adj052", question: "She was _____ about the outcome of the investigation. (anxiety)", options: ["anxiety", "anxious", "anxiously", "anxiousness"], correctIndex: 1, explanation: "'Anxious' là tính từ của danh từ 'anxiety', nghĩa 'lo lắng'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'anxious about'. Danh từ 'anxiety' và trạng từ 'anxiously' đều không thể đứng ở vị trí vị ngữ tính từ này." },
  { id: "adj053", question: "The results were _____ compared to last year's figures. (encourage)", options: ["encourage", "encouragement", "encouraging", "encouraged"], correctIndex: 2, explanation: "'Encouraging' (đuôi '-ing') mô tả sự vật/kết quả mang lại sự khích lệ - ở đây là 'the results'. Sau 'were' cần tính từ làm vị ngữ. Phân biệt với 'encouraged' (đuôi '-ed'), chỉ dùng cho người cảm thấy được khích lệ, không phù hợp để mô tả bản thân kết quả như câu này." },
  { id: "adj054", question: "He was _____ by the complexity of the task ahead. (intimidate)", options: ["intimidate", "intimidating", "intimidation", "intimidated"], correctIndex: 3, explanation: "'Intimidated' (đuôi '-ed') diễn tả cảm giác e sợ/nản lòng của người, đúng với chủ ngữ 'he'. Cấu trúc quen thuộc là 'be intimidated by something'. Đối lập với 'intimidating' (đuôi '-ing'), chỉ dùng để mô tả sự việc gây ra cảm giác đó, ví dụ 'the task was intimidating', không phù hợp khi chủ ngữ là người như ở đây." },
  { id: "adj055", question: "The assignment was _____ for students of all levels. (challenge)", options: ["challenge", "challenged", "challenging", "challengeable"], correctIndex: 2, explanation: "'Challenging' (đuôi '-ing') mô tả sự việc mang tính thử thách - ở đây là 'the assignment'. Sau 'was' cần tính từ làm vị ngữ. 'Challenged' (đuôi '-ed') lại dùng cho người gặp khó khăn/bị thử thách, không phù hợp để mô tả bản thân bài tập như trong câu này." },
  { id: "adj056", question: "She felt _____ after completing her first solo project. (confidence)", options: ["confidence", "confidently", "confident", "confide"], correctIndex: 2, explanation: "'Confident' là tính từ của danh từ 'confidence', nghĩa 'tự tin'. Sau động từ cảm giác 'felt' cần tính từ làm bổ ngữ. 'Confide' (động từ, nghĩa 'tâm sự, tin tưởng ai đó') hoàn toàn khác nghĩa và sai vị trí ngữ pháp so với 'confident'." },
  { id: "adj057", question: "The manager's explanation was rather _____. (ambiguity)", options: ["ambiguity", "ambiguously", "ambiguate", "ambiguous"], correctIndex: 3, explanation: "'Ambiguous' là tính từ của danh từ 'ambiguity', nghĩa 'mơ hồ, không rõ ràng'. Sau 'rather' (khá là) cần tính từ làm vị ngữ. 'Ambiguously' (trạng từ) không thể tự đứng làm vị ngữ như 'ambiguous' trong câu này." },
  { id: "adj058", question: "She is known for her _____ and direct communication style. (frankness)", options: ["frankness", "frankly", "frank", "franker"], correctIndex: 2, explanation: "'Frank' là tính từ của danh từ 'frankness', nghĩa 'thẳng thắn'. Đứng trước danh từ 'communication style' (được nối bằng 'and' với tính từ 'direct') nên cần một tính từ tương ứng. 'Frankly' (trạng từ, thường dùng để mở đầu câu như 'frankly speaking') không thể bổ nghĩa trực tiếp cho danh từ như 'frank'." },
  { id: "adj059", question: "His research method was _____ and easy to replicate. (transparency)", options: ["transparency", "transparently", "transparent", "transparence"], correctIndex: 2, explanation: "'Transparent' là tính từ của danh từ 'transparency', nghĩa 'minh bạch, rõ ràng'. Sau 'was' cần tính từ làm vị ngữ. 'Transparently' (trạng từ) và 'transparence' (dạng danh từ ít dùng) đều sai vị trí ngữ pháp so với 'transparent'." },
  { id: "adj060", question: "The new design is both _____ and environmentally friendly. (sustain)", options: ["sustain", "sustainably", "sustainable", "sustainability"], correctIndex: 2, explanation: "'Sustainable' là tính từ tạo từ động từ 'sustain' bằng đuôi '-able', nghĩa 'bền vững'. Cấu trúc 'both...and' nối với tính từ 'environmentally friendly', nên chỗ trống cũng cần tính từ. Danh từ 'sustainability' và trạng từ 'sustainably' đều không thể đứng song song với một tính từ trong cấu trúc này." },
  { id: "adj061", question: "The committee was _____ to approve the budget increase. (reluctance)", options: ["reluctance", "reluctantly", "reluctant", "relucter"], correctIndex: 2, explanation: "'Reluctant' là tính từ của danh từ 'reluctance', nghĩa 'miễn cưỡng, ngần ngại'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'reluctant to do something'. 'Reluctantly' (trạng từ) không thể tự đứng làm vị ngữ như 'reluctant' trong câu này." },
  { id: "adj062", question: "Her _____ nature makes her popular among her colleagues. (approach)", options: ["approach", "approachingly", "approachable", "approached"], correctIndex: 2, explanation: "'Approachable' là tính từ tạo từ động từ 'approach' bằng đuôi '-able', nghĩa 'dễ gần, thân thiện'. Đứng trước danh từ 'nature' cần một tính từ để bổ nghĩa. 'Approached' (quá khứ phân từ mang nghĩa bị động 'được tiếp cận') hoàn toàn khác nghĩa và không hợp ngữ cảnh mô tả tính cách." },
  { id: "adj063", question: "The project received _____ feedback from all stakeholders. (mix)", options: ["mix", "mixing", "mixed", "mixer"], correctIndex: 2, explanation: "'Mixed' là tính từ (vốn từ quá khứ phân từ của 'mix') mang nghĩa 'lẫn lộn, trái chiều', thường đi với danh từ trong cụm cố định 'mixed feedback/reviews'. Đứng trước danh từ 'feedback' cần một tính từ để bổ nghĩa. 'Mixing' (V-ing, nghĩa 'đang trộn') không phù hợp về nghĩa lẫn cách dùng quen thuộc này." },
  { id: "adj064", question: "She remained _____ despite the mounting pressure. (compose)", options: ["compose", "composition", "composedly", "composed"], correctIndex: 3, explanation: "'Composed' là tính từ (dạng quá khứ phân từ của 'compose') mang nghĩa 'điềm tĩnh, bình tĩnh'. Sau động từ liên kết 'remained' cần tính từ làm vị ngữ. 'Composition' (danh từ, nghĩa 'tác phẩm/thành phần') hoàn toàn khác nghĩa và sai vị trí so với 'composed'." },
  { id: "adj065", question: "The treatment proved _____ for the majority of patients. (benefit)", options: ["benefit", "benefiting", "beneficial", "beneficially"], correctIndex: 2, explanation: "'Beneficial' là tính từ của danh từ 'benefit', nghĩa 'có lợi, mang lại lợi ích'. Sau 'proved' cần tính từ làm bổ ngữ. 'Benefiting' (V-ing, dạng đang hưởng lợi) mang nghĩa chủ động khác, không phù hợp để mô tả tác dụng của phương pháp điều trị như câu này." },
  { id: "adj066", question: "Her _____ dedication to the cause inspired many. (unwaver)", options: ["unwaver", "unwavering", "unwaveringly", "unwavered"], correctIndex: 1, explanation: "'Unwavering' là tính từ (không có danh từ 'unwaver' độc lập, đây là tính từ ghép từ tiền tố phủ định 'un-' + 'wavering'), mang nghĩa 'kiên định, không lay chuyển'. Đứng trước danh từ 'dedication' cần một tính từ để bổ nghĩa. 'Unwavered' không phải là dạng chuẩn trong tiếng Anh, khác với 'unwavering' vốn dùng phổ biến." },
  { id: "adj067", question: "The instructions were clear and _____ to follow. (straightforward)", options: ["straightforward", "straightforwardly", "straightforwardness", "straightforwarded"], correctIndex: 0, explanation: "'Straightforward' là tính từ ghép, mang nghĩa 'dễ hiểu, rõ ràng, không phức tạp'. Sau liên từ 'and' nối với tính từ 'clear' nên chỗ trống cũng cần một tính từ. 'Straightforwardly' (trạng từ) và 'straightforwardness' (danh từ) đều không thể đứng song song với tính từ 'clear' trong cấu trúc này." },
  { id: "adj068", question: "She was _____ in her support for the new initiative. (wholehearted)", options: ["wholehearted", "wholeheartedly", "wholeheartedness", "wholeheartening"], correctIndex: 0, explanation: "'Wholehearted' là tính từ ghép, mang nghĩa 'hết lòng, toàn tâm toàn ý'. Sau 'was' cần tính từ làm vị ngữ. 'Wholeheartedly' (trạng từ) không thể tự đứng làm vị ngữ như 'wholehearted' trong câu này." },
  { id: "adj069", question: "The evidence presented was _____ and hard to dispute. (convince)", options: ["convince", "convinced", "convincingly", "convincing"], correctIndex: 3, explanation: "'Convincing' (đuôi '-ing') mô tả sự vật/bằng chứng có sức thuyết phục - ở đây là 'the evidence'. Sau 'was' cần tính từ làm vị ngữ. Phân biệt với 'convinced' (đuôi '-ed'), chỉ dùng cho người bị thuyết phục, không phù hợp để mô tả bản thân bằng chứng như câu này." },
  { id: "adj070", question: "She was _____ by the evidence and changed her opinion. (convince)", options: ["convince", "convincing", "convincingly", "convinced"], correctIndex: 3, explanation: "'Convinced' (đuôi '-ed') diễn tả trạng thái của người bị thuyết phục, đúng với chủ ngữ 'she'. Cấu trúc quen thuộc 'be convinced by something'. Đối lập với 'convincing' (đuôi '-ing'), dùng để mô tả bản thân bằng chứng/lập luận gây ra sự thuyết phục, không phù hợp khi chủ ngữ là người như ở đây." },
  { id: "adj071", question: "The _____ nature of the job makes it both exciting and unpredictable. (vary)", options: ["vary", "various", "variously", "variable"], correctIndex: 3, explanation: "'Variable' là tính từ tạo từ động từ 'vary' bằng đuôi '-able', mang nghĩa 'hay thay đổi, bất định'. Đứng trước danh từ 'nature' cần một tính từ để bổ nghĩa. 'Various' (tính từ khác nghĩa, nghĩa 'nhiều loại khác nhau') dễ gây nhầm lẫn về hình thức nhưng không phù hợp ngữ nghĩa bằng 'variable' ở đây." },
  { id: "adj072", question: "His response to the crisis was _____ and decisive. (promptness)", options: ["promptness", "promptly", "prompt", "prompting"], correctIndex: 2, explanation: "'Prompt' là tính từ tương ứng với danh từ 'promptness', nghĩa 'nhanh chóng, kịp thời'. Sau 'was' và trước liên từ 'and' nối với tính từ 'decisive' nên chỗ trống cũng cần một tính từ. 'Promptly' (trạng từ) không thể đứng song song với tính từ 'decisive' trong cấu trúc này." },
  { id: "adj073", question: "The data collected was highly _____ to the research question. (relevance)", options: ["relevance", "relevantly", "relevant", "relevation"], correctIndex: 2, explanation: "'Relevant' là tính từ của danh từ 'relevance', nghĩa 'liên quan, thích đáng'. Sau 'highly' cần tính từ làm vị ngữ, đi cùng giới từ 'relevant to'. 'Relevantly' (trạng từ) và 'relevation' (không phải từ chuẩn) đều không phù hợp ở vị trí này." },
  { id: "adj074", question: "She is _____ in completing tasks exactly as instructed. (precision)", options: ["precision", "precisely", "precise", "preciseness"], correctIndex: 2, explanation: "'Precise' là tính từ của danh từ 'precision', nghĩa 'chính xác, tỉ mỉ'. Sau 'is' cần tính từ làm vị ngữ. 'Preciseness' (một dạng danh từ ít dùng) và trạng từ 'precisely' đều sai vị trí ngữ pháp so với 'precise' ở đây." },
  { id: "adj075", question: "The new regulations are _____ and easy to comply with. (clarity)", options: ["clarity", "clarify", "clarifying", "clear"], correctIndex: 3, explanation: "'Clear' là tính từ của danh từ 'clarity', nghĩa 'rõ ràng'. Sau 'are' và trước liên từ 'and' nối với cụm tính từ 'easy to comply with', chỗ trống cần một tính từ tương tự. 'Clarify' (động từ) và 'clarifying' (V-ing) đều sai vị trí so với tính từ 'clear'." },
  { id: "adj076", question: "She showed a _____ improvement in her test scores. (remark)", options: ["remark", "remarkably", "remarked", "remarkable"], correctIndex: 3, explanation: "'Remarkable' là tính từ của 'remark', đuôi '-able' mang nghĩa 'đáng chú ý'. Đứng trước danh từ 'improvement' cần một tính từ để bổ nghĩa. 'Remarkably' (trạng từ) không thể đứng trực tiếp trước danh từ như 'remarkable' trong câu này." },
  { id: "adj077", question: "The speaker's tone was _____ and reassuring. (calm)", options: ["calm", "calmness", "calmly", "calmer"], correctIndex: 0, explanation: "'Calm' là tính từ gốc, mang nghĩa 'điềm tĩnh, bình tĩnh'. Sau 'was' và trước liên từ 'and' nối với tính từ 'reassuring', chỗ trống cần một tính từ. 'Calmness' (danh từ) và 'calmer' (dạng so sánh hơn, không phù hợp ngữ cảnh không so sánh ở đây) đều không đúng." },
  { id: "adj078", question: "He was _____ to take on more responsibilities. (willing)", options: ["willingness", "will", "willingly", "willing"], correctIndex: 3, explanation: "'Willing' là tính từ của danh từ 'willingness', nghĩa 'sẵn lòng'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'willing to do something'. 'Willingly' (trạng từ) không thể tự đứng làm vị ngữ như 'willing' ở đây." },
  { id: "adj079", question: "The findings were extremely _____ and changed our approach. (significance)", options: ["significance", "significantly", "signifying", "significant"], correctIndex: 3, explanation: "'Significant' là tính từ của danh từ 'significance', nghĩa 'quan trọng, đáng kể'. Sau 'extremely' cần tính từ làm vị ngữ. 'Signifying' (V-ing của 'signify', nghĩa 'biểu thị') mang nghĩa khác và sai vị trí ngữ pháp so với 'significant'." },
  { id: "adj080", question: "Her contributions to the project were truly _____. (value)", options: ["value", "valued", "valuably", "valuable"], correctIndex: 3, explanation: "'Valuable' là tính từ của danh từ/động từ 'value', đuôi '-able' mang nghĩa 'có giá trị'. Sau 'truly' cần tính từ làm vị ngữ. 'Valued' (quá khứ phân từ, nghĩa 'được đánh giá cao/được coi trọng') mang sắc thái hơi khác, trong khi 'valuable' phù hợp hơn khi nói về giá trị khách quan của đóng góp." },
  { id: "adj081", question: "The training program was _____ for all new staff. (mandate)", options: ["mandate", "mandatorily", "mandating", "mandatory"], correctIndex: 3, explanation: "'Mandatory' là tính từ của danh từ 'mandate', nghĩa 'bắt buộc'. Sau 'was' cần tính từ làm vị ngữ. 'Mandatorily' (trạng từ) không thể tự đứng làm vị ngữ như 'mandatory' trong câu này." },
  { id: "adj082", question: "He is very _____ when it comes to his work schedule. (flexibly)", options: ["flexible", "flexibly", "flex", "flexibility"], correctIndex: 0, explanation: "'Flexible' là tính từ, mang nghĩa 'linh hoạt'. Sau 'very' cần tính từ để mô tả tính cách của 'he'. 'Flexibly' (trạng từ) và 'flexibility' (danh từ) đều sai vị trí ngữ pháp so với 'flexible' đứng sau 'very'." },
  { id: "adj083", question: "The team's performance was _____ despite a lack of resources. (commend)", options: ["commend", "commending", "commendable", "commendably"], correctIndex: 2, explanation: "'Commendable' là tính từ tạo từ động từ 'commend' bằng đuôi '-able', nghĩa 'đáng khen ngợi'. Sau 'was' cần tính từ làm vị ngữ. 'Commendably' (trạng từ) không thể tự đứng làm vị ngữ như 'commendable' ở đây." },
  { id: "adj084", question: "She is _____ for her attention to detail in all her work. (fame)", options: ["fame", "famed", "famously", "famous"], correctIndex: 3, explanation: "'Famous' là tính từ của danh từ 'fame', nghĩa 'nổi tiếng'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'famous for'. 'Famed' (cũng có nghĩa tương tự nhưng ít trang trọng và ít phổ biến hơn trong văn nói thông thường) và trạng từ 'famously' đều không phù hợp bằng 'famous' ở vị trí này." },
  { id: "adj085", question: "The deadline is _____ and cannot be extended. (flex)", options: ["flexible", "flexibly", "flex", "inflexible"], correctIndex: 3, explanation: "'Inflexible' là tính từ mang tiền tố phủ định 'in-' cộng với 'flexible', nghĩa 'cứng nhắc, không thể thay đổi' - đối lập hoàn toàn với 'flexible'. Ngữ cảnh 'cannot be extended' cho thấy cần một tính từ mang nghĩa phủ định như 'inflexible', chứ không phải 'flexible' (linh hoạt) vốn mang nghĩa ngược lại." },
  { id: "adj086", question: "The staff were _____ by the new manager's leadership style. (motivate)", options: ["motivate", "motivation", "motivating", "motivated"], correctIndex: 3, explanation: "'Motivated' (đuôi '-ed') diễn tả cảm giác được truyền cảm hứng của người, đúng với chủ ngữ 'the staff'. Cấu trúc quen thuộc 'be motivated by something'. Đối lập với 'motivating' (đuôi '-ing'), dùng để mô tả bản thân sự việc/phong cách gây ra cảm hứng, không phù hợp khi chủ ngữ là người như ở đây." },
  { id: "adj087", question: "Her work on the project was _____ to the team's success. (pivotal)", options: ["pivotal", "pivotally", "pivot", "pivoting"], correctIndex: 0, explanation: "'Pivotal' là tính từ, mang nghĩa 'then chốt, mang tính quyết định'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'pivotal to'. 'Pivotally' (trạng từ) và 'pivot' (danh từ/động từ, nghĩa 'trục xoay/xoay chuyển') đều sai vị trí hoặc từ loại so với 'pivotal'." },
  { id: "adj088", question: "The contract terms seemed _____ at first glance. (complicate)", options: ["complicate", "complicated", "complication", "complicating"], correctIndex: 1, explanation: "'Complicated' là tính từ (dạng quá khứ phân từ của 'complicate'), mang nghĩa 'phức tạp'. Sau động từ liên kết 'seemed' cần tính từ làm vị ngữ. 'Complication' (danh từ, nghĩa 'sự phức tạp/biến chứng') và 'complicating' (V-ing) đều sai vị trí ngữ pháp so với 'complicated'." },
  { id: "adj089", question: "She has been _____ to both praise and criticism throughout her career. (expose)", options: ["expose", "exposer", "exposed", "exposing"], correctIndex: 2, explanation: "'Exposed' là tính từ/dạng quá khứ phân từ của 'expose', mang nghĩa 'bị/được tiếp xúc với'. Sau 'has been' cần tính từ/phân từ làm vị ngữ, đi cùng giới từ 'exposed to'. 'Exposer' (danh từ chỉ người vạch trần điều gì) và 'exposing' (V-ing, nghĩa chủ động 'đang phơi bày') đều không phù hợp ngữ cảnh bị động ở đây." },
  { id: "adj090", question: "The team's _____ response to the crisis prevented further damage. (swift)", options: ["swift", "swiftness", "swiftly", "swifter"], correctIndex: 0, explanation: "'Swift' là tính từ gốc (danh từ liên quan là 'swiftness'), mang nghĩa 'nhanh chóng'. Đứng trước danh từ 'response' cần một tính từ để bổ nghĩa. 'Swiftly' (trạng từ) không thể bổ nghĩa trực tiếp cho danh từ như 'swift' ở đây." },
  { id: "adj091", question: "He was _____ to give up even when progress was slow. (determination)", options: ["determination", "determined", "determining", "determine"], correctIndex: 1, explanation: "'Determined' là tính từ (dạng quá khứ phân từ của 'determine'), mang nghĩa 'quyết tâm'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'determined to do something'. Danh từ 'determination' và V-ing 'determining' đều sai vị trí ngữ pháp so với 'determined'." },
  { id: "adj092", question: "The solution proposed was both _____ and practical. (elegance)", options: ["elegance", "elegantly", "elegance", "elegant"], correctIndex: 3, explanation: "'Elegant' là tính từ của danh từ 'elegance', nghĩa 'tinh tế, gọn gàng, khéo léo'. Cấu trúc 'both...and' nối với tính từ 'practical', nên chỗ trống cũng cần tính từ. 'Elegantly' (trạng từ) không thể đứng song song với tính từ 'practical' trong cấu trúc này." },
  { id: "adj093", question: "The increase in productivity was _____ after the new system was installed. (immediacy)", options: ["immediacy", "immediately", "immediateness", "immediate"], correctIndex: 3, explanation: "'Immediate' là tính từ của danh từ 'immediacy', nghĩa 'ngay lập tức'. Sau 'was' cần tính từ làm vị ngữ. 'Immediately' (trạng từ) không thể tự đứng làm vị ngữ như 'immediate' trong câu này." },
  { id: "adj094", question: "She is _____ in her commitment to workplace equality. (unwaver)", options: ["unwavering", "unwaver", "unwaveringly", "unwavered"], correctIndex: 0, explanation: "'Unwavering' là tính từ ghép, mang nghĩa 'kiên định, không lay chuyển'. Sau 'is' cần tính từ làm vị ngữ. 'Unwaveringly' (trạng từ) không thể tự đứng làm vị ngữ, còn 'unwavered' không phải dạng chuẩn trong tiếng Anh." },
  { id: "adj095", question: "The committee's recommendations were _____ and well-reasoned. (sound)", options: ["sound", "soundly", "sounding", "soundness"], correctIndex: 0, explanation: "'Sound' là tính từ (đồng âm khác nghĩa với danh từ 'sound' - âm thanh), ở đây mang nghĩa 'chắc chắn, hợp lý, đáng tin cậy'. Sau 'were' và trước liên từ 'and' nối với cụm tính từ 'well-reasoned', chỗ trống cần một tính từ tương tự. 'Soundly' (trạng từ) và 'soundness' (danh từ) đều sai vị trí ngữ pháp." },
  { id: "adj096", question: "The new product line is both _____ and affordable. (innovate)", options: ["innovate", "innovative", "innovation", "innovatively"], correctIndex: 1, explanation: "'Innovative' là tính từ của động từ 'innovate', mang nghĩa 'sáng tạo, đổi mới'. Cấu trúc 'both...and' nối với tính từ 'affordable', nên chỗ trống cũng cần tính từ. Danh từ 'innovation' và trạng từ 'innovatively' đều không thể đứng song song với tính từ 'affordable' ở đây." },
  { id: "adj097", question: "He is _____ about meeting new people and learning new things. (passion)", options: ["passion", "passionately", "passionateness", "passionate"], correctIndex: 3, explanation: "'Passionate' là tính từ của danh từ 'passion', nghĩa 'đam mê, nhiệt huyết'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'passionate about'. 'Passionately' (trạng từ) và 'passionateness' (dạng danh từ ít dùng) đều sai vị trí so với 'passionate'." },
  { id: "adj098", question: "The team's _____ performance has put them at the top of the league. (consist)", options: ["consist", "consistently", "consistent", "consistency"], correctIndex: 2, explanation: "'Consistent' là tính từ của danh từ 'consistency', nghĩa 'ổn định, nhất quán'. Đứng trước danh từ 'performance' cần một tính từ để bổ nghĩa. 'Consistently' (trạng từ) không thể bổ nghĩa trực tiếp cho danh từ như 'consistent' ở đây." },
  { id: "adj099", question: "She is _____ to change her schedule to accommodate clients. (flexibly)", options: ["flexible", "flexibly", "flex", "inflexible"], correctIndex: 0, explanation: "'Flexible' là tính từ, mang nghĩa 'linh hoạt, dễ thích nghi'. Sau 'is' cần tính từ làm vị ngữ, đi cùng cấu trúc 'flexible to do something' (ở đây gần nghĩa sẵn sàng thay đổi). 'Inflexible' (mang nghĩa ngược lại, 'cứng nhắc') không phù hợp ngữ cảnh 'accommodate clients' đòi hỏi sự linh hoạt." },
  { id: "adj100", question: "The documentary was both _____ and eye-opening. (inform)", options: ["inform", "informative", "information", "informedly"], correctIndex: 1, explanation: "'Informative' là tính từ tạo từ động từ 'inform' bằng đuôi '-ive', nghĩa 'giàu thông tin, bổ ích'. Cấu trúc 'both...and' nối với tính từ 'eye-opening', nên chỗ trống cũng cần tính từ. Danh từ 'information' và trạng từ 'informedly' đều không phù hợp vị trí này." },
  { id: "adj101", question: "She is _____ in her ability to negotiate deals. (skill)", options: ["skill", "skillfully", "skilled", "skillfulness"], correctIndex: 2, explanation: "'Skilled' là tính từ tạo từ danh từ 'skill' bằng đuôi '-ed', nghĩa 'lành nghề, thành thạo'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'skilled in'. 'Skillfulness' (danh từ) và trạng từ 'skillfully' đều sai vị trí ngữ pháp so với 'skilled'." },
  { id: "adj102", question: "The product design is both _____ and user-friendly. (function)", options: ["function", "functioned", "functional", "functionally"], correctIndex: 2, explanation: "'Functional' là tính từ của danh từ/động từ 'function', đuôi '-al' mang nghĩa 'thực dụng, có công năng tốt'. Cấu trúc 'both...and' nối với tính từ 'user-friendly', nên chỗ trống cũng cần tính từ. Trạng từ 'functionally' và động từ 'functioned' đều sai vị trí ở đây." },
  { id: "adj103", question: "She is deeply _____ to traditional values and ethics. (commitment)", options: ["commitment", "committed", "committing", "commit"], correctIndex: 1, explanation: "'Committed' là tính từ (dạng quá khứ phân từ của 'commit'), mang nghĩa 'tận tâm, cam kết'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'committed to'. Danh từ 'commitment' và V-ing 'committing' đều sai vị trí ngữ pháp so với 'committed'." },
  { id: "adj104", question: "The new policy was met with _____ opposition from the public. (wide)", options: ["wide", "wideness", "widely", "widen"], correctIndex: 0, explanation: "'Wide' là tính từ gốc, ở đây mang nghĩa 'rộng khắp'. Đứng trước danh từ 'opposition' cần một tính từ để bổ nghĩa (dù 'widespread' sẽ tự nhiên hơn, 'wide' vẫn là tính từ hợp lệ ở vị trí này). 'Widely' (trạng từ) và 'widen' (động từ) đều không thể đứng trực tiếp trước danh từ như 'wide'." },
  { id: "adj105", question: "His writing style is both _____ and persuasive. (eloquence)", options: ["eloquence", "eloquently", "eloquent", "eloquentness"], correctIndex: 2, explanation: "'Eloquent' là tính từ của danh từ 'eloquence', nghĩa 'hùng hồn, lưu loát'. Cấu trúc 'both...and' nối với tính từ 'persuasive', nên chỗ trống cũng cần tính từ. Trạng từ 'eloquently' và dạng danh từ ít dùng 'eloquentness' đều không phù hợp vị trí này." },
  { id: "adj106", question: "The manager's feedback was _____ and helped the team improve. (construct)", options: ["construct", "constructed", "constructive", "constructively"], correctIndex: 2, explanation: "'Constructive' là tính từ tạo từ động từ 'construct' bằng đuôi '-ive', mang nghĩa 'mang tính xây dựng'. Sau 'was' cần tính từ làm vị ngữ. 'Constructed' (quá khứ phân từ, nghĩa 'được xây dựng theo nghĩa đen') và trạng từ 'constructively' đều không phù hợp ngữ nghĩa/ngữ pháp bằng 'constructive' ở đây." },
  { id: "adj107", question: "She was completely _____ by the scale of the challenge. (overwhelm)", options: ["overwhelm", "overwhelming", "overwhelmingly", "overwhelmed"], correctIndex: 3, explanation: "'Overwhelmed' (đuôi '-ed') diễn tả cảm giác bị choáng ngợp/áp đảo của người, đúng với chủ ngữ 'she'. Cấu trúc quen thuộc 'be overwhelmed by something'. Đối lập với 'overwhelming' (đuôi '-ing'), dùng để mô tả bản thân sự việc gây ra cảm giác đó, ví dụ 'the challenge was overwhelming', không phù hợp khi chủ ngữ là người như ở đây." },
  { id: "adj108", question: "The task was _____ but ultimately very rewarding. (demand)", options: ["demand", "demanding", "demanded", "demandingly"], correctIndex: 1, explanation: "'Demanding' (đuôi '-ing') mô tả sự việc đòi hỏi nhiều nỗ lực/công sức - ở đây là 'the task'. Sau 'was' cần tính từ làm vị ngữ. 'Demanded' (đuôi '-ed', dạng bị động 'được yêu cầu') mang nghĩa khác hẳn và không phù hợp để mô tả bản thân tính chất công việc như câu này." },
  { id: "adj109", question: "The conference was _____ attended by delegates from 50 countries. (remark)", options: ["remark", "remarkably", "remarkable", "remarked"], correctIndex: 2, explanation: "'Remarkable' là tính từ của 'remark', nghĩa 'đáng chú ý, ấn tượng'. Trong câu này, 'remarkable' đóng vai trò vị ngữ mô tả 'the conference' (hội nghị đáng chú ý), còn cụm 'attended by delegates from 50 countries' bổ sung thêm thông tin. Cần phân biệt với 'remarkably' (trạng từ) - nếu dùng để bổ nghĩa cho động từ 'attended' thì câu sẽ mang nghĩa khác ('được tham dự một cách đáng kể'), nhưng ở đây ta mô tả bản thân hội nghị nên chọn tính từ 'remarkable'." },
  { id: "adj110", question: "She is _____ of the risks involved in the new venture. (awareness)", options: ["awareness", "aware", "awarely", "awareness"], correctIndex: 1, explanation: "'Aware' là tính từ của danh từ 'awareness', nghĩa 'nhận thức được, ý thức được'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'aware of'. 'Awarely' không phải là một từ chuẩn trong tiếng Anh, nên tính từ 'aware' mới là lựa chọn đúng." },
  { id: "adj111", question: "The new system proved far more _____ than the old one. (rely)", options: ["rely", "reliably", "reliable", "reliance"], correctIndex: 2, explanation: "'Reliable' là tính từ tạo từ động từ 'rely' bằng đuôi '-able', nghĩa 'đáng tin cậy'. Sau cấu trúc so sánh hơn 'more' cần một tính từ. Danh từ 'reliance' và trạng từ 'reliably' đều sai vị trí ngữ pháp so với 'reliable' trong mẫu 'more + adjective'." },
  { id: "adj112", question: "The community was very _____ to the idea of a new park. (reception)", options: ["reception", "receptive", "receptively", "recepted"], correctIndex: 1, explanation: "'Receptive' là tính từ của danh từ 'reception', đuôi '-ive' mang nghĩa 'cởi mở đón nhận'. Sau 'very' cần tính từ làm vị ngữ, đi cùng giới từ 'receptive to'. Danh từ 'reception' (nghĩa 'sự tiếp nhận/buổi tiệc chiêu đãi') không thể đứng ở vị trí tính từ này." },
  { id: "adj113", question: "She made a _____ decision to leave her stable job. (boldness)", options: ["boldness", "bold", "boldly", "bolden"], correctIndex: 1, explanation: "'Bold' là tính từ của danh từ 'boldness', nghĩa 'táo bạo, dũng cảm'. Đứng trước danh từ 'decision' cần một tính từ để bổ nghĩa. 'Boldly' (trạng từ) không thể bổ nghĩa trực tiếp cho danh từ như 'bold' ở đây." },
  { id: "adj114", question: "The training course was _____ and covered many practical skills. (comprehension)", options: ["comprehension", "comprehensively", "comprehend", "comprehensive"], correctIndex: 3, explanation: "'Comprehensive' là tính từ của danh từ 'comprehension', mang nghĩa 'toàn diện, đầy đủ'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'comprehensively' và động từ 'comprehend' đều sai vị trí ngữ pháp so với 'comprehensive' ở đây." },
  { id: "adj115", question: "He is _____ about the future of the company. (pessimism)", options: ["pessimism", "pessimistically", "pessimist", "pessimistic"], correctIndex: 3, explanation: "'Pessimistic' là tính từ của danh từ 'pessimism', đuôi '-ic' mang nghĩa 'bi quan'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'pessimistic about'. Danh từ chỉ người 'pessimist' và trạng từ 'pessimistically' đều sai vị trí ở đây." },
  { id: "adj116", question: "The manager's approach was both _____ and empathetic. (authority)", options: ["authority", "authoritatively", "authoritative", "authorization"], correctIndex: 2, explanation: "'Authoritative' là tính từ của danh từ 'authority', nghĩa 'có uy quyền, đáng tin'. Cấu trúc 'both...and' nối với tính từ 'empathetic', nên chỗ trống cũng cần tính từ. Trạng từ 'authoritatively' và danh từ 'authorization' đều không phù hợp vị trí này." },
  { id: "adj117", question: "She was deeply _____ by the news of the accident. (affect)", options: ["affect", "affected", "affecting", "affectedly"], correctIndex: 1, explanation: "'Affected' là tính từ (dạng quá khứ phân từ của 'affect'), mang nghĩa 'bị tác động, xúc động'. Sau 'was' và 'deeply' cần tính từ làm vị ngữ, đi cùng giới từ 'affected by'. 'Affecting' (đuôi '-ing') lại dùng để mô tả sự việc gây ra tác động, ví dụ 'an affecting story', không phù hợp khi chủ ngữ là người như câu này." },
  { id: "adj118", question: "The company's growth strategy has been remarkably _____. (success)", options: ["success", "successful", "successfully", "successor"], correctIndex: 1, explanation: "'Successful' là tính từ của danh từ 'success', đuôi '-ful' mang nghĩa 'thành công'. Sau 'remarkably' cần tính từ làm vị ngữ. Danh từ 'success' và danh từ chỉ người 'successor' (người kế nhiệm) đều sai vị trí/nghĩa so với 'successful'." },
  { id: "adj119", question: "The new employee was extremely _____ and learned quickly. (adapt)", options: ["adapt", "adapting", "adaptable", "adaptation"], correctIndex: 2, explanation: "'Adaptable' là tính từ tạo từ động từ 'adapt' bằng đuôi '-able', nghĩa 'dễ thích nghi'. Sau 'extremely' cần tính từ làm vị ngữ. V-ing 'adapting' và danh từ 'adaptation' đều sai vị trí ngữ pháp so với 'adaptable' ở đây." },
  { id: "adj120", question: "She is _____ in her support for environmental causes. (passion)", options: ["passion", "passionate", "passionately", "passionateness"], correctIndex: 1, explanation: "'Passionate' là tính từ của danh từ 'passion', nghĩa 'đam mê, nhiệt huyết'. Sau 'is' cần tính từ làm vị ngữ. Trạng từ 'passionately' và dạng danh từ ít dùng 'passionateness' đều sai vị trí so với 'passionate'." },
  { id: "adj121", question: "The instructions provided were _____ but effective. (minimize)", options: ["minimized", "minimal", "minimally", "minimize"], correctIndex: 1, explanation: "'Minimal' là tính từ liên quan đến động từ 'minimize', mang nghĩa 'tối thiểu, ít ỏi'. Sau 'were' cần tính từ làm vị ngữ, trước liên từ 'but' nối với tính từ 'effective'. 'Minimized' (quá khứ phân từ, nghĩa 'đã được giảm thiểu') mang sắc thái khác, không tự nhiên bằng 'minimal' khi mô tả bản thân các hướng dẫn ngắn gọn." },
  { id: "adj122", question: "She was _____ to admit her mistake in front of the team. (reluctance)", options: ["reluctance", "reluctantly", "reluctant", "relucter"], correctIndex: 2, explanation: "'Reluctant' là tính từ của danh từ 'reluctance', nghĩa 'miễn cưỡng, ngần ngại'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'reluctant to do something'. 'Reluctantly' (trạng từ) không thể tự đứng làm vị ngữ như 'reluctant' ở đây." },
  { id: "adj123", question: "The project's success was heavily _____ on good teamwork. (depend)", options: ["depend", "dependant", "dependency", "dependent"], correctIndex: 3, explanation: "'Dependent' là tính từ của động từ 'depend', nghĩa 'phụ thuộc'. Sau 'was heavily' cần tính từ làm vị ngữ, đi cùng giới từ 'dependent on'. 'Dependant' (danh từ chỉ 'người phụ thuộc', ví dụ trong hồ sơ thuế) và danh từ 'dependency' đều sai từ loại/vị trí so với 'dependent'." },
  { id: "adj124", question: "His plan was _____ and lacked detail. (vague)", options: ["vague", "vagueness", "vaguely", "vaguer"], correctIndex: 0, explanation: "'Vague' là tính từ của danh từ 'vagueness', nghĩa 'mơ hồ, không rõ ràng'. Sau 'was' cần tính từ làm vị ngữ. 'Vaguely' (trạng từ) và 'vaguer' (dạng so sánh hơn, không phù hợp khi câu không so sánh) đều sai so với 'vague'." },
  { id: "adj125", question: "She was _____ to take on the leadership role when asked. (hesitate)", options: ["hesitate", "hesitant", "hesitation", "hesitatingly"], correctIndex: 1, explanation: "'Hesitant' là tính từ tạo từ động từ 'hesitate' bằng đuôi '-ant', nghĩa 'do dự, ngần ngại'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'hesitant to do something'. Danh từ 'hesitation' và trạng từ 'hesitatingly' đều sai vị trí ngữ pháp ở đây." },
  { id: "adj126", question: "The team's morale remained _____ despite setbacks. (height)", options: ["height", "highly", "high", "heightened"], correctIndex: 2, explanation: "'High' là tính từ gốc (danh từ liên quan là 'height'), mang nghĩa 'cao'. Sau động từ liên kết 'remained' cần tính từ làm vị ngữ, tạo thành cụm cố định 'morale remained high'. 'Highly' (trạng từ) chỉ dùng để bổ nghĩa cho tính từ/động từ khác (ví dụ 'highly effective'), không thể tự làm vị ngữ như 'high' ở đây." },
  { id: "adj127", question: "Her feedback was _____ and encouraged the team to work harder. (motivate)", options: ["motivating", "motivated", "motivation", "motivate"], correctIndex: 0, explanation: "'Motivating' (đuôi '-ing') mô tả sự việc/lời phản hồi tạo ra động lực - ở đây là 'her feedback'. Chỗ trống đứng ngay sau chủ ngữ 'her feedback was' cần một tính từ làm vị ngữ. Đối lập với 'motivated' (đuôi '-ed'), chỉ dùng cho người cảm thấy có động lực, không phù hợp để mô tả bản thân lời phản hồi như câu này." },
  { id: "adj128", question: "The solution was _____ and achieved exactly what was needed. (elegance)", options: ["elegance", "elegantly", "elegant", "elegantness"], correctIndex: 2, explanation: "'Elegant' là tính từ của danh từ 'elegance', nghĩa 'tinh tế, gọn gàng'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'elegantly' và dạng danh từ ít dùng 'elegantness' đều sai vị trí so với 'elegant' ở đây." },
  { id: "adj129", question: "She is _____ in her decision once she has made up her mind. (resolve)", options: ["resolve", "resolved", "resolvedly", "resolvable"], correctIndex: 1, explanation: "'Resolved' là tính từ (dạng quá khứ phân từ của 'resolve'), mang nghĩa 'kiên quyết, dứt khoát'. Sau 'is' cần tính từ làm vị ngữ. Danh từ/động từ gốc 'resolve' và 'resolvedly' (trạng từ hiếm dùng) đều không phù hợp bằng 'resolved' ở vị trí này." },
  { id: "adj130", question: "The new regulations are _____ for all businesses operating in this sector. (oblige)", options: ["oblige", "obliged", "obligation", "obligatory"], correctIndex: 3, explanation: "'Obligatory' là tính từ liên quan đến động từ 'oblige', mang nghĩa 'bắt buộc'. Sau 'are' cần tính từ làm vị ngữ. 'Obliged' (quá khứ phân từ, nghĩa 'cảm thấy có nghĩa vụ', thường dùng cho người) và danh từ 'obligation' đều không phù hợp bằng 'obligatory' khi mô tả tính chất của quy định." },
  { id: "adj131", question: "The campaign was _____ successful and exceeded all targets. (phenom)", options: ["phenomenally", "phenomenal", "phenomenon", "phenomenalize"], correctIndex: 1, explanation: "'Phenomenal' là tính từ của danh từ 'phenomenon', mang nghĩa 'phi thường, xuất sắc'. Trong câu này, 'phenomenal' được xem như tính từ mô tả trực tiếp 'the campaign' (chiến dịch phi thường), đứng liền trước tính từ 'successful' để nhấn mạnh mức độ thành công vượt bậc. Phân biệt với 'phenomenally' (trạng từ, thường bổ nghĩa cho một tính từ khác như 'phenomenally successful') và 'phenomenon' (danh từ, nghĩa 'hiện tượng') - không phù hợp làm tính từ bổ nghĩa ở đây." },
  { id: "adj132", question: "She is _____ about environmental issues and actively campaigns. (passion)", options: ["passion", "passionately", "passionateness", "passionate"], correctIndex: 3, explanation: "'Passionate' là tính từ của danh từ 'passion', nghĩa 'đam mê, nhiệt huyết'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'passionate about'. Trạng từ 'passionately' và dạng danh từ ít dùng 'passionateness' đều sai vị trí so với 'passionate'." },
  { id: "adj133", question: "The committee was _____ with the results of the audit. (satisfy)", options: ["satisfy", "satisfied", "satisfying", "satisfactorily"], correctIndex: 1, explanation: "'Satisfied' (đuôi '-ed') diễn tả cảm giác hài lòng của người/nhóm người, phù hợp với chủ ngữ 'the committee'. Cấu trúc quen thuộc 'be satisfied with something'. Đối lập với 'satisfying' (đuôi '-ing'), dùng để mô tả sự việc mang lại cảm giác hài lòng, ví dụ 'the results were satisfying', không phù hợp khi chủ ngữ là người/nhóm cảm nhận như câu này." },
  { id: "adj134", question: "His arguments were _____ and difficult to counter. (logic)", options: ["logic", "logically", "logical", "logician"], correctIndex: 2, explanation: "'Logical' là tính từ của danh từ 'logic', nghĩa 'hợp lý, logic'. Đứng sau 'were' cần tính từ làm vị ngữ mô tả 'his arguments'. Trạng từ 'logically' và danh từ chỉ người 'logician' (nhà logic học) đều sai vị trí/nghĩa so với 'logical'." },
  { id: "adj135", question: "She is _____ to criticism and always responds professionally. (immunity)", options: ["immune", "immunity", "immunely", "immunized"], correctIndex: 0, explanation: "'Immune' là tính từ của danh từ 'immunity', nghĩa 'miễn nhiễm, không bị ảnh hưởng'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'immune to'. 'Immunely' (không phải từ chuẩn) và 'immunized' (quá khứ phân từ, nghĩa 'được tiêm chủng') đều không phù hợp ở đây." },
  { id: "adj136", question: "The proposal was _____ and addressed all key concerns. (thorough)", options: ["thoroughly", "thoroughness", "thorougher", "thorough"], correctIndex: 3, explanation: "'Thorough' là tính từ gốc, mang nghĩa 'kỹ lưỡng, toàn diện'. Sau 'was' cần tính từ làm vị ngữ. 'Thoroughly' (trạng từ) và 'thoroughness' (danh từ) đều sai vị trí ngữ pháp so với 'thorough' ở đây." },
  { id: "adj137", question: "He was _____ in his efforts to improve team morale. (tire)", options: ["tire", "tiring", "tiredness", "tireless"], correctIndex: 3, explanation: "'Tireless' là tính từ mang đuôi phủ định '-less' cộng với gốc 'tire', nghĩa 'không biết mệt mỏi, bền bỉ'. Sau 'was' cần tính từ làm vị ngữ. 'Tiring' (đuôi '-ing', mô tả thứ gây mệt mỏi) và 'tiredness' (danh từ) đều không phù hợp nghĩa/vị trí so với 'tireless' ở đây." },
  { id: "adj138", question: "The team was _____ to receive such high praise. (please)", options: ["please", "pleasingly", "pleased", "pleasing"], correctIndex: 2, explanation: "'Pleased' (đuôi '-ed') diễn tả cảm giác hài lòng/vui mừng của người, phù hợp với chủ ngữ 'the team'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'pleased to do something'. Đối lập với 'pleasing' (đuôi '-ing'), dùng để mô tả sự việc mang lại cảm giác hài lòng, không phù hợp khi chủ ngữ là người cảm nhận như câu này." },
  { id: "adj139", question: "Her presentation was _____ and left a lasting impression. (polish)", options: ["polish", "polishing", "polished", "polishedly"], correctIndex: 2, explanation: "'Polished' là tính từ (dạng quá khứ phân từ của 'polish'), mang nghĩa 'tinh tế, trau chuốt'. Sau 'was' cần tính từ làm vị ngữ. 'Polishing' (V-ing, nghĩa 'đang đánh bóng') mang nghĩa hành động chủ động, không phù hợp để mô tả tính chất hoàn thiện của bài thuyết trình như 'polished'." },
  { id: "adj140", question: "The _____ nature of the work required constant attention. (repeat)", options: ["repeat", "repeatedly", "repetitive", "repetition"], correctIndex: 2, explanation: "'Repetitive' là tính từ liên quan đến động từ 'repeat', đuôi '-ive' mang nghĩa 'lặp đi lặp lại'. Đứng trước danh từ 'nature' cần một tính từ để bổ nghĩa. Trạng từ 'repeatedly' và danh từ 'repetition' đều không thể đứng trực tiếp trước danh từ như 'repetitive' ở đây." },
  { id: "adj141", question: "She was _____ to start a new chapter in her career. (eager)", options: ["eagerness", "eagerly", "eager", "eagered"], correctIndex: 2, explanation: "'Eager' là tính từ gốc (danh từ liên quan là 'eagerness'), mang nghĩa 'háo hức'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'eager to do something'. 'Eagerly' (trạng từ) không thể tự đứng làm vị ngữ như 'eager' trong câu này." },
  { id: "adj142", question: "The new plan was _____ to address longstanding issues. (intend)", options: ["intend", "intended", "intention", "intending"], correctIndex: 1, explanation: "'Intended' là tính từ/dạng quá khứ phân từ của 'intend', mang nghĩa 'được dự định'. Sau 'was' cần tính từ/phân từ làm vị ngữ, đi cùng cấu trúc 'intended to do something'. Danh từ 'intention' và V-ing 'intending' đều sai vị trí ngữ pháp so với 'intended'." },
  { id: "adj143", question: "She was _____ for her contributions and received an award. (celebrate)", options: ["celebrate", "celebrating", "celebrated", "celebration"], correctIndex: 2, explanation: "'Celebrated' là tính từ (dạng quá khứ phân từ của 'celebrate'), mang nghĩa 'được tôn vinh, nổi tiếng'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'celebrated for'. V-ing 'celebrating' và danh từ 'celebration' đều sai vị trí ngữ pháp so với 'celebrated'." },
  { id: "adj144", question: "The findings were _____ with current scientific understanding. (consist)", options: ["consist", "consistently", "consistency", "consistent"], correctIndex: 3, explanation: "'Consistent' là tính từ liên quan đến động từ 'consist', nghĩa 'nhất quán, phù hợp'. Sau 'were' cần tính từ làm vị ngữ, đi cùng giới từ 'consistent with'. Trạng từ 'consistently' và danh từ 'consistency' đều sai vị trí so với 'consistent' ở đây." },
  { id: "adj145", question: "The manager's approach was too _____ and lacked flexibility. (rigid)", options: ["rigid", "rigidness", "rigidly", "rigidity"], correctIndex: 0, explanation: "'Rigid' là tính từ gốc (danh từ liên quan là 'rigidity'), mang nghĩa 'cứng nhắc'. Sau 'too' cần tính từ làm vị ngữ. 'Rigidly' (trạng từ) và 'rigidness' (dạng danh từ ít dùng) đều sai vị trí ngữ pháp so với 'rigid'." },
  { id: "adj146", question: "She was _____ to change her mind, even with strong evidence. (reluctance)", options: ["reluctance", "reluctant", "reluctantly", "relucter"], correctIndex: 1, explanation: "'Reluctant' là tính từ của danh từ 'reluctance', nghĩa 'miễn cưỡng'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'reluctant to do something'. 'Reluctantly' (trạng từ) không thể tự đứng làm vị ngữ như 'reluctant' ở đây." },
  { id: "adj147", question: "The report was _____ reviewed before publication. (technical)", options: ["technically", "technical", "technicality", "technician"], correctIndex: 1, explanation: "'Technical' là tính từ mang nghĩa 'mang tính kỹ thuật, chuyên môn'. Trong câu này, 'technical' được dùng để mô tả tính chất của quá trình xem xét - 'a technical review' (một cuộc rà soát mang tính kỹ thuật) - nên đóng vai trò bổ nghĩa cho cụm 'reviewed' như một tính từ gắn với danh từ ẩn 'review'. Phân biệt với 'technically' (trạng từ, thường dùng để bổ nghĩa cho động từ hoặc mang nghĩa 'về mặt kỹ thuật mà nói') và 'technician' (danh từ chỉ người, nghĩa 'kỹ thuật viên') - không phù hợp ở vị trí này." },
  { id: "adj148", question: "She made a _____ recovery from her illness. (remark)", options: ["remark", "remarkably", "remarkable", "remarked"], correctIndex: 2, explanation: "'Remarkable' là tính từ của 'remark', nghĩa 'đáng chú ý, ấn tượng'. Đứng trước danh từ 'recovery' cần một tính từ để bổ nghĩa. 'Remarkably' (trạng từ) không thể bổ nghĩa trực tiếp cho danh từ như 'remarkable' ở đây." },
  { id: "adj149", question: "He was _____ in his dedication to customer satisfaction. (tire)", options: ["tireless", "tire", "tiredly", "tired"], correctIndex: 0, explanation: "'Tireless' là tính từ mang đuôi phủ định '-less', nghĩa 'không biết mệt mỏi'. Sau 'was' cần tính từ làm vị ngữ. 'Tired' (đuôi '-ed', nghĩa 'cảm thấy mệt') mang nghĩa hoàn toàn trái ngược và không phù hợp với ngữ cảnh ca ngợi sự tận tụy như câu này." },
  { id: "adj150", question: "Her _____ attitude made her a natural leader. (posit)", options: ["posit", "positively", "positivity", "positive"], correctIndex: 3, explanation: "'Positive' là tính từ của danh từ 'positivity', nghĩa 'tích cực'. Đứng trước danh từ 'attitude' cần một tính từ để bổ nghĩa. Trạng từ 'positively' không thể bổ nghĩa trực tiếp cho danh từ như 'positive' ở đây." },
  { id: "adj151", question: "The research findings were _____ to practitioners in the field. (value)", options: ["value", "valuing", "valuably", "valuable"], correctIndex: 3, explanation: "'Valuable' là tính từ của danh từ/động từ 'value', nghĩa 'có giá trị'. Sau 'were' cần tính từ làm vị ngữ, đi cùng giới từ 'valuable to'. V-ing 'valuing' và trạng từ 'valuably' đều sai vị trí ngữ pháp so với 'valuable'." },
  { id: "adj152", question: "She proved _____ in all aspects of the job. (competence)", options: ["competence", "competently", "competency", "competent"], correctIndex: 3, explanation: "'Competent' là tính từ của danh từ 'competence', nghĩa 'có năng lực'. Sau 'proved' cần tính từ làm bổ ngữ. Trạng từ 'competently' và danh từ 'competency' đều sai vị trí ngữ pháp so với 'competent' ở đây." },
  { id: "adj153", question: "The atmosphere at the conference was _____ and encouraging. (posit)", options: ["positivity", "positively", "positive", "posit"], correctIndex: 2, explanation: "'Positive' là tính từ, mang nghĩa 'tích cực'. Sau 'was' và trước liên từ 'and' nối với tính từ 'encouraging', chỗ trống cũng cần tính từ. Danh từ 'positivity' và trạng từ 'positively' đều sai vị trí so với 'positive' ở đây." },
  { id: "adj154", question: "The manager's feedback was _____ of the team's hard work. (appreciate)", options: ["appreciate", "appreciation", "appreciative", "appreciatively"], correctIndex: 2, explanation: "'Appreciative' là tính từ liên quan đến động từ 'appreciate', đuôi '-ive' mang nghĩa 'biết ơn, đánh giá cao'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'appreciative of'. Danh từ 'appreciation' và trạng từ 'appreciatively' đều sai vị trí ngữ pháp ở đây." },
  { id: "adj155", question: "The outcome was _____ and all parties were satisfied. (favor)", options: ["favor", "favorably", "favorableness", "favorable"], correctIndex: 3, explanation: "'Favorable' là tính từ của danh từ 'favor', đuôi '-able' mang nghĩa 'thuận lợi, tốt đẹp'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'favorably' và dạng danh từ ít dùng 'favorableness' đều sai vị trí so với 'favorable'." },
  { id: "adj156", question: "She is _____ about her health and exercises daily. (consciousness)", options: ["consciousness", "consciously", "conscious", "conscience"], correctIndex: 2, explanation: "'Conscious' là tính từ của danh từ 'consciousness', nghĩa 'ý thức được, chú ý đến' (như trong cụm 'health-conscious'). Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'conscious about/of'. Trạng từ 'consciously' và danh từ 'conscience' (nghĩa 'lương tâm', khác nghĩa hoàn toàn) đều không phù hợp ở đây." },
  { id: "adj157", question: "The project was _____ due to budget cuts. (scale back)", options: ["scaled-back", "scale-back", "scaling-back", "scaled back"], correctIndex: 0, explanation: "'Scaled-back' là tính từ ghép (dạng quá khứ phân từ 'scaled' + 'back'), mang nghĩa 'bị cắt giảm quy mô'. Sau 'was' cần một tính từ/phân từ làm vị ngữ. Đây là dạng ghép có gạch nối chuẩn, khác với các biến thể không đúng ngữ pháp như 'scale-back' hay 'scaling-back' xuất hiện trong các lựa chọn còn lại." },
  { id: "adj158", question: "He was _____ in his refusal to compromise on quality. (adamant)", options: ["adamant", "adamantly", "adamance", "adamantness"], correctIndex: 0, explanation: "'Adamant' là tính từ gốc, mang nghĩa 'cứng đầu, kiên quyết không lay chuyển'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'adamantly' và các dạng danh từ ít dùng 'adamance'/'adamantness' đều sai vị trí ngữ pháp so với 'adamant'." },
  { id: "adj159", question: "The team's _____ approach to problem-solving is highly effective. (system)", options: ["system", "systematically", "systematic", "systematics"], correctIndex: 2, explanation: "'Systematic' là tính từ của danh từ 'system', đuôi '-ic' mang nghĩa 'có hệ thống, bài bản'. Đứng trước danh từ 'approach' cần một tính từ để bổ nghĩa. Trạng từ 'systematically' không thể bổ nghĩa trực tiếp cho danh từ như 'systematic' ở đây." },
  { id: "adj160", question: "She was _____ in her communication and always got the message across. (effectiveness)", options: ["effectiveness", "effective", "effectively", "effectuation"], correctIndex: 1, explanation: "'Effective' là tính từ của danh từ 'effectiveness', nghĩa 'hiệu quả'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'effectively' và danh từ ít dùng 'effectuation' đều sai vị trí ngữ pháp so với 'effective' ở đây." },
  { id: "adj161", question: "The new strategy proved highly _____ in reducing costs. (effectiveness)", options: ["effectiveness", "effective", "effectively", "effector"], correctIndex: 1, explanation: "'Effective' là tính từ của danh từ 'effectiveness', nghĩa 'hiệu quả'. Sau 'proved highly' cần tính từ làm bổ ngữ. Trạng từ 'effectively' và danh từ chỉ người/vật 'effector' đều sai vị trí ngữ pháp so với 'effective' ở đây." },
  { id: "adj162", question: "She was _____ to see that her work was being recognized. (gratitude)", options: ["gratitude", "grateful", "gratefully", "gratefulness"], correctIndex: 1, explanation: "'Grateful' là tính từ của danh từ 'gratitude', đuôi '-ful' mang nghĩa 'biết ơn'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'grateful to see/for something'. Trạng từ 'gratefully' và dạng danh từ ít dùng 'gratefulness' đều sai vị trí so với 'grateful'." },
  { id: "adj163", question: "The design of the building was both _____ and functional. (aesthetics)", options: ["aesthetics", "aesthetically", "aesthetic", "aesthetician"], correctIndex: 2, explanation: "'Aesthetic' là tính từ của danh từ 'aesthetics', mang nghĩa 'thẩm mỹ'. Cấu trúc 'both...and' nối với tính từ 'functional', nên chỗ trống cũng cần tính từ. Trạng từ 'aesthetically' và danh từ chỉ người 'aesthetician' (chuyên viên thẩm mỹ) đều không phù hợp vị trí này." },
  { id: "adj164", question: "He is _____ about his work and never cuts corners. (thorough)", options: ["thoroughly", "thoroughness", "thorough", "thorougher"], correctIndex: 2, explanation: "'Thorough' là tính từ gốc, mang nghĩa 'kỹ lưỡng, cẩn thận'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'thorough about'. Trạng từ 'thoroughly' và danh từ 'thoroughness' đều sai vị trí ngữ pháp so với 'thorough' ở đây." },
  { id: "adj165", question: "The board was _____ with the financial projections for next year. (encourage)", options: ["encourage", "encouragingly", "encouragement", "encouraged"], correctIndex: 3, explanation: "'Encouraged' (đuôi '-ed') diễn tả cảm giác được khích lệ của người/nhóm người, phù hợp với chủ ngữ 'the board'. Đối lập với 'encouraging' (đuôi '-ing'), dùng để mô tả sự việc mang lại sự khích lệ, ví dụ 'the projections were encouraging', không phù hợp khi chủ ngữ là người/nhóm cảm nhận như câu này." },
  { id: "adj166", question: "The policy change was _____ welcomed by industry experts. (broad)", options: ["broad", "breadth", "broadly", "broaden"], correctIndex: 2, explanation: "'Broadly' là trạng từ của tính từ 'broad', dùng để bổ nghĩa cho động từ ở dạng bị động 'welcomed' (được đón nhận rộng rãi), nên đây là một trong số ít câu của bộ bài tập này mà đáp án đúng lại là trạng từ chứ không phải tính từ. Nếu dùng tính từ 'broad' đứng trước động từ thì câu sẽ sai ngữ pháp, vì tính từ không thể bổ nghĩa trực tiếp cho động từ. Hãy chú ý vị trí của từ cần điền: đứng trước một động từ ở dạng bị động thì luôn cần trạng từ, khác với các câu khác trong bài đứng trước danh từ hoặc sau liên động từ mới cần tính từ." },
  { id: "adj167", question: "The manager was _____ in her assessment of the situation. (accuracy)", options: ["accuracy", "accurate", "accurately", "accurateness"], correctIndex: 1, explanation: "'Accurate' là tính từ của danh từ 'accuracy', nghĩa 'chính xác'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'accurately' và dạng danh từ ít dùng 'accurateness' đều sai vị trí ngữ pháp so với 'accurate' ở đây." },
  { id: "adj168", question: "She was _____ in addressing the concerns of her team. (prompt)", options: ["promptness", "promptly", "prompt", "prompting"], correctIndex: 2, explanation: "'Prompt' là tính từ tương ứng với danh từ 'promptness', mang nghĩa 'kịp thời, nhanh nhẹn'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'promptly' và V-ing 'prompting' đều sai vị trí ngữ pháp so với 'prompt' ở đây." },
  { id: "adj169", question: "The report was _____ and left no room for misinterpretation. (unambiguous)", options: ["unambiguous", "unambiguously", "unambiguity", "unambiguousness"], correctIndex: 0, explanation: "'Unambiguous' là tính từ mang tiền tố phủ định 'un-' cộng với 'ambiguous', nghĩa 'rõ ràng, không mơ hồ'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'unambiguously' và các dạng danh từ 'unambiguity'/'unambiguousness' đều sai vị trí ngữ pháp so với 'unambiguous' ở đây." },
  { id: "adj170", question: "She was _____ by the support she received from her community. (move)", options: ["move", "moving", "movingly", "moved"], correctIndex: 3, explanation: "'Moved' (đuôi '-ed') diễn tả cảm giác cảm động của người, phù hợp với chủ ngữ 'she'. Cấu trúc quen thuộc 'be moved by something'. Đối lập với 'moving' (đuôi '-ing'), dùng để mô tả sự việc gây ra cảm động, ví dụ 'a moving story', không phù hợp khi chủ ngữ là người cảm nhận như câu này." },
  { id: "adj171", question: "The audience found the keynote speech _____ and inspiring. (thought-provoke)", options: ["thought-provoking", "thought-provoked", "thought-provocation", "thought-provoker"], correctIndex: 0, explanation: "'Thought-provoking' là tính từ ghép (đuôi '-ing'), mang nghĩa 'kích thích tư duy, gợi suy nghĩ'. Đây là mẫu câu 'find something + adjective', nên chỗ trống cần tính từ để mô tả 'the keynote speech' - vật gây ra sự suy ngẫm cho người nghe. 'Thought-provoked' không phải là cách dùng chuẩn, vì bản thân bài phát biểu là thứ chủ động kích thích suy nghĩ chứ không 'bị kích thích'." },
  { id: "adj172", question: "Her _____ understanding of the subject made her the best candidate. (depth)", options: ["depth", "deeply", "deep", "deepen"], correctIndex: 2, explanation: "'Deep' là tính từ của danh từ 'depth', nghĩa 'sâu sắc'. Đứng trước danh từ 'understanding' cần một tính từ để bổ nghĩa. Trạng từ 'deeply' không thể bổ nghĩa trực tiếp cho danh từ như 'deep' ở đây." },
  { id: "adj173", question: "The organization is _____ for its charity work in the region. (well-know)", options: ["well-known", "well-knowing", "well-knowledgeable", "well-knows"], correctIndex: 0, explanation: "'Well-known' là tính từ ghép (trạng từ 'well' + quá khứ phân từ 'known'), mang nghĩa 'được biết đến rộng rãi'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'well-known for'. Các dạng còn lại như 'well-knowing' hay 'well-knows' không phải cách dùng chuẩn trong tiếng Anh." },
  { id: "adj174", question: "The team showed _____ resilience under extreme pressure. (remark)", options: ["remark", "remarkably", "remarked", "remarkable"], correctIndex: 3, explanation: "'Remarkable' là tính từ của 'remark', nghĩa 'đáng chú ý, ấn tượng'. Đứng trước danh từ 'resilience' cần một tính từ để bổ nghĩa. Trạng từ 'remarkably' không thể bổ nghĩa trực tiếp cho danh từ như 'remarkable' ở đây." },
  { id: "adj175", question: "She was _____ to receive feedback and used it to improve. (open)", options: ["openness", "openly", "open", "opening"], correctIndex: 2, explanation: "'Open' là tính từ tương ứng với danh từ 'openness', nghĩa 'cởi mở'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'open to'. Trạng từ 'openly' và danh động từ 'opening' đều sai vị trí ngữ pháp so với 'open' ở đây." },
  { id: "adj176", question: "The company's values are deeply _____ in its corporate culture. (embed)", options: ["embed", "embedding", "embeddedness", "embedded"], correctIndex: 3, explanation: "'Embedded' là tính từ (dạng quá khứ phân từ của 'embed'), mang nghĩa 'được gắn sâu vào, ăn sâu vào'. Sau 'are deeply' cần tính từ/phân từ làm vị ngữ. Danh từ trừu tượng 'embeddedness' và V-ing 'embedding' đều sai vị trí ngữ pháp so với 'embedded' ở đây." },
  { id: "adj177", question: "The candidate was _____ for the senior management role. (suit)", options: ["suit", "suiting", "suitably", "suitable"], correctIndex: 3, explanation: "'Suitable' là tính từ của động từ 'suit', đuôi '-able' mang nghĩa 'phù hợp'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'suitable for'. Trạng từ 'suitably' và V-ing 'suiting' đều sai vị trí ngữ pháp so với 'suitable' ở đây." },
  { id: "adj178", question: "She was _____ of the challenges ahead and prepared accordingly. (awareness)", options: ["awareness", "aware", "awarely", "awakened"], correctIndex: 1, explanation: "'Aware' là tính từ của danh từ 'awareness', nghĩa 'nhận thức được'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'aware of'. 'Awakened' (quá khứ phân từ của 'awaken', nghĩa 'được đánh thức') mang nghĩa khác hẳn và không phù hợp ngữ cảnh nhận thức về rủi ro như câu này." },
  { id: "adj179", question: "The new policy is _____ with international best practices. (align)", options: ["align", "aligning", "alignment", "aligned"], correctIndex: 3, explanation: "'Aligned' là tính từ (dạng quá khứ phân từ của 'align'), mang nghĩa 'phù hợp, nhất quán với'. Sau 'is' cần tính từ/phân từ làm vị ngữ, đi cùng giới từ 'aligned with'. Danh từ 'alignment' và V-ing 'aligning' đều sai vị trí ngữ pháp so với 'aligned' ở đây." },
  { id: "adj180", question: "She was _____ in managing stakeholder expectations throughout the project. (skill)", options: ["skill", "skillfulness", "skilled", "skillfully"], correctIndex: 2, explanation: "'Skilled' là tính từ của danh từ 'skill', đuôi '-ed' mang nghĩa 'lành nghề, thành thạo'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'skilled in'. Danh từ 'skillfulness' và trạng từ 'skillfully' đều sai vị trí ngữ pháp so với 'skilled' ở đây." },
  { id: "adj181", question: "The results of the experiment were _____ with the original hypothesis. (inconsistency)", options: ["inconsistency", "inconsistently", "inconsistent", "consist"], correctIndex: 2, explanation: "'Inconsistent' là tính từ mang tiền tố phủ định 'in-' cộng với 'consistent', nghĩa 'không nhất quán, mâu thuẫn'. Sau 'were' cần tính từ làm vị ngữ, đi cùng giới từ 'inconsistent with'. Danh từ 'inconsistency' và trạng từ 'inconsistently' đều sai vị trí ngữ pháp so với 'inconsistent' ở đây." },
  { id: "adj182", question: "She was _____ to answer questions without preparation. (willing)", options: ["willingness", "will", "willingly", "willing"], correctIndex: 3, explanation: "'Willing' là tính từ của danh từ 'willingness', nghĩa 'sẵn lòng'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'willing to do something'. Trạng từ 'willingly' không thể tự đứng làm vị ngữ như 'willing' ở đây." },
  { id: "adj183", question: "The data collected was _____ to support the proposed changes. (sufficiency)", options: ["sufficiency", "sufficiently", "sufficed", "sufficient"], correctIndex: 3, explanation: "'Sufficient' là tính từ của danh từ 'sufficiency', nghĩa 'đủ, đầy đủ'. Sau 'was' cần tính từ làm vị ngữ. Trạng từ 'sufficiently' và động từ 'sufficed' (dạng quá khứ của 'suffice') đều sai vị trí/từ loại so với 'sufficient' ở đây." },
  { id: "adj184", question: "She remains _____ about achieving her long-term goals. (optimism)", options: ["optimism", "optimistically", "optimist", "optimistic"], correctIndex: 3, explanation: "'Optimistic' là tính từ của danh từ 'optimism', đuôi '-ic' mang nghĩa 'lạc quan'. Sau 'remains' cần tính từ làm vị ngữ, đi cùng giới từ 'optimistic about'. Danh từ chỉ người 'optimist' và trạng từ 'optimistically' đều sai vị trí ngữ pháp so với 'optimistic' ở đây." },
  { id: "adj185", question: "The team's response was _____ and showed great professionalism. (measure)", options: ["measuring", "measured", "measuredly", "measure"], correctIndex: 1, explanation: "'Measured' là tính từ (dạng quá khứ phân từ của 'measure'), mang nghĩa 'cân nhắc, thận trọng, chừng mực'. Sau 'was' cần tính từ làm vị ngữ. V-ing 'measuring' và trạng từ hiếm dùng 'measuredly' đều không phù hợp bằng 'measured' khi mô tả tính chất phản ứng điềm tĩnh của đội." },
  { id: "adj186", question: "The manager was very _____ about the team's progress this quarter. (encouragement)", options: ["encouragement", "encourage", "encouraging", "encouraged"], correctIndex: 2, explanation: "'Encouraging' ở đây được dùng như tính từ mô tả người mang thái độ khích lệ, động viên người khác (nghĩa gần với 'helpful, supportive') - khác với cặp cảm xúc thông thường '-ed/-ing' vì 'the manager' là người chủ động tạo ra sự khích lệ cho đội, chứ không phải người 'được' khích lệ. Sau 'was very' cần tính từ làm vị ngữ. Nếu dùng 'encouraged' (đuôi '-ed') câu sẽ mang nghĩa khác hẳn - rằng chính người quản lý là người được khích lệ bởi ai đó, không đúng với ý câu muốn nói ở đây." },
  { id: "adj187", question: "His approach to the issue was both _____ and fair. (balance)", options: ["balance", "balanced", "balancing", "balancedly"], correctIndex: 1, explanation: "'Balanced' là tính từ tạo từ danh từ 'balance' bằng đuôi '-ed', mang nghĩa 'cân bằng, khách quan'. Cấu trúc 'both...and' nối với tính từ 'fair', nên chỗ trống cũng cần tính từ. Danh từ 'balance' và V-ing 'balancing' đều sai vị trí ngữ pháp so với 'balanced' ở đây." },
  { id: "adj188", question: "The new employee is _____ to the company's values from day one. (commit)", options: ["committed", "committing", "commit", "commitment"], correctIndex: 0, explanation: "'Committed' là tính từ (dạng quá khứ phân từ của 'commit'), mang nghĩa 'tận tụy, cam kết'. Sau 'is' cần tính từ làm vị ngữ, đi cùng giới từ 'committed to'. V-ing 'committing' và danh từ 'commitment' đều sai vị trí ngữ pháp so với 'committed'." },
  { id: "adj189", question: "She was totally _____ with the progress of the project. (satisfy)", options: ["satisfy", "satisfying", "satisfaction", "satisfied"], correctIndex: 3, explanation: "'Satisfied' (đuôi '-ed') diễn tả cảm giác hài lòng của người, phù hợp với chủ ngữ 'she'. Cấu trúc quen thuộc 'be satisfied with something'. Đối lập với 'satisfying' (đuôi '-ing'), dùng để mô tả sự việc mang lại cảm giác hài lòng, không phù hợp khi chủ ngữ là người cảm nhận như câu này." },
  { id: "adj190", question: "The mentor was very _____ and helped her navigate her career. (support)", options: ["support", "supported", "supportingly", "supportive"], correctIndex: 3, explanation: "'Supportive' là tính từ của danh từ/động từ 'support', đuôi '-ive' mang nghĩa 'hỗ trợ, ủng hộ'. Sau 'very' cần tính từ làm vị ngữ. Quá khứ phân từ 'supported' (nghĩa 'được hỗ trợ', mang nghĩa bị động) và trạng từ hiếm dùng 'supportingly' đều không phù hợp bằng 'supportive' ở đây." },
  { id: "adj191", question: "The committee was _____ about the proposed budget cuts. (concern)", options: ["concern", "concerned", "concerning", "concernedly"], correctIndex: 1, explanation: "'Concerned' (đuôi '-ed') diễn tả cảm giác lo lắng của người/nhóm người, phù hợp với chủ ngữ 'the committee'. Cấu trúc quen thuộc 'be concerned about something'. Đối lập với 'concerning' (đuôi '-ing'), dùng để mô tả sự việc gây ra lo lắng, ví dụ 'concerning news', không phù hợp khi chủ ngữ là người/nhóm cảm nhận như câu này." },
  { id: "adj192", question: "The news about the merger was _____. (concern)", options: ["concern", "concerned", "concernedly", "concerning"], correctIndex: 3, explanation: "'Concerning' (đuôi '-ing') mô tả sự việc/tin tức gây ra sự lo lắng - ở đây là 'the news about the merger'. Sau 'was' cần tính từ làm vị ngữ. Đối lập với 'concerned' (đuôi '-ed'), chỉ dùng cho người cảm thấy lo lắng, không phù hợp để mô tả bản thân tin tức như câu này." },
  { id: "adj193", question: "She was _____ to explore new career opportunities. (enthuse)", options: ["enthuse", "enthusiastically", "enthusiasm", "enthusiastic"], correctIndex: 3, explanation: "'Enthusiastic' là tính từ của danh từ 'enthusiasm', đuôi '-ic' mang nghĩa 'nhiệt tình, hăng hái'. Sau 'was' cần tính từ làm vị ngữ, đi cùng cấu trúc 'enthusiastic to do something'. Trạng từ 'enthusiastically' và động từ gốc 'enthuse' đều sai vị trí ngữ pháp so với 'enthusiastic' ở đây." },
  { id: "adj194", question: "The new approach proved _____ more effective than expected. (consider)", options: ["consider", "considerably", "considerable", "consideration"], correctIndex: 2, explanation: "'Considerable' là tính từ liên quan đến động từ 'consider', mang nghĩa 'đáng kể, to lớn'. Trong câu này, 'considerable' được dùng để nhấn mạnh mức độ chênh lệch của 'more effective' theo hướng bổ nghĩa cho cụm so sánh, dù về mặt chuẩn mực nhiều người bản ngữ sẽ dùng trạng từ 'considerably' để bổ nghĩa cho tính từ so sánh 'more effective' cho chặt chẽ hơn. Phân biệt với danh từ 'consideration' - không thể đứng ở vị trí bổ nghĩa này." },
  { id: "adj195", question: "She was _____ in her support, even when things got difficult. (waver)", options: ["unwavering", "waver", "wavering", "waveringly"], correctIndex: 0, explanation: "'Unwavering' là tính từ ghép, mang nghĩa 'kiên định, không lay chuyển'. Sau 'was' cần tính từ làm vị ngữ. 'Wavering' (đuôi '-ing', nghĩa 'dao động, lung lay') mang nghĩa trái ngược hoàn toàn, và 'waveringly' (trạng từ) cũng sai vị trí so với 'unwavering' ở đây." },
  { id: "adj196", question: "The company's _____ commitment to innovation has driven its success. (tire)", options: ["tireless", "tire", "tiredly", "tired"], correctIndex: 0, explanation: "'Tireless' là tính từ mang đuôi phủ định '-less', nghĩa 'không biết mệt mỏi'. Đứng trước danh từ 'commitment' cần một tính từ để bổ nghĩa. 'Tired' (đuôi '-ed', nghĩa 'cảm thấy mệt') mang nghĩa trái ngược và không phù hợp để ca ngợi sự cam kết bền bỉ như câu này." },
  { id: "adj197", question: "She was _____ in following up on every detail of the project. (diligence)", options: ["diligence", "diligently", "diligent", "diligencer"], correctIndex: 2, explanation: "'Diligent' là tính từ của danh từ 'diligence', nghĩa 'chăm chỉ, cần mẫn'. Sau 'was' cần tính từ làm vị ngữ, đi cùng giới từ 'diligent in'. Trạng từ 'diligently' và danh từ gán người 'diligencer' (không phải từ chuẩn) đều sai vị trí ngữ pháp so với 'diligent' ở đây." },
  { id: "adj198", question: "The organization's response to the crisis was _____ and well-coordinated. (promptness)", options: ["promptness", "promptly", "prompting", "prompt"], correctIndex: 3, explanation: "'Prompt' là tính từ tương ứng với danh từ 'promptness', mang nghĩa 'kịp thời'. Sau 'was' và trước liên từ 'and' nối với tính từ 'well-coordinated', chỗ trống cần một tính từ tương tự. Trạng từ 'promptly' và V-ing 'prompting' đều sai vị trí ngữ pháp so với 'prompt' ở đây." },
  { id: "adj199", question: "She felt _____ after giving a presentation to 500 people. (exhilarate)", options: ["exhilarate", "exhilarating", "exhilaration", "exhilarated"], correctIndex: 3, explanation: "'Exhilarated' (đuôi '-ed') diễn tả cảm giác phấn khích của người, phù hợp với chủ ngữ 'she' sau động từ cảm giác 'felt'. Đối lập với 'exhilarating' (đuôi '-ing'), dùng để mô tả trải nghiệm/sự việc gây ra cảm giác phấn khích, ví dụ 'the experience was exhilarating', không phù hợp khi chủ ngữ là người cảm nhận như câu này." },
  { id: "adj200", question: "The feedback session was _____ and helped the team improve. (exhilarate)", options: ["exhilarate", "exhilarated", "exhilaration", "exhilarating"], correctIndex: 3, explanation: "'Exhilarating' (đuôi '-ing') mô tả sự việc/buổi họp mang lại cảm giác phấn khích - ở đây là 'the feedback session'. Sau 'was' cần tính từ làm vị ngữ. Đối lập với 'exhilarated' (đuôi '-ed'), chỉ dùng cho người cảm thấy phấn khích, không phù hợp để mô tả bản thân buổi họp như câu này." },
];
